function recordSimulatedTeam(clubId,goals,conceded){
 const picks=bestLineup(clubId,club(clubId).formation),lineup=picks.lineup.filter(Boolean),subs=picks.bench.filter(id=>id&&player(id).primary!=='GK').slice(0,3);
 const attackers=lineup.filter(id=>['ST','LW','RW','AM','CM'].includes(player(id).primary));
 const scorers=attackers.length?attackers:lineup.filter(id=>player(id).primary!=='GK');
 const goalsBy={},assistsBy={};
 for(let g=0;g<goals;g++){const scorer=rand(scorers);if(!scorer)break;goalsBy[scorer]=(goalsBy[scorer]||0)+1;const creator=rand(attackers.filter(id=>id!==scorer));if(creator&&Math.random()<.74)assistsBy[creator]=(assistsBy[creator]||0)+1}
 const cards=simulatedCards(lineup);if(Math.random()<.08){const hurt=rand(lineup.filter(id=>eligible(id)));if(hurt)applyInjury(hurt,'Match injury')}const dismissed=new Map(cards.filter(e=>e.type==='red').map(e=>[e.playerId,e.minute]));
 const replaced=lineup.filter(id=>player(id).primary!=='GK'&&!dismissed.has(id)).slice(-subs.length);subs.length=Math.min(subs.length,replaced.length);
 for(const id of lineup)recordStats(id,{start:true,minutes:dismissed.get(id)??(replaced.includes(id)?75:90),goals:goalsBy[id]||0,assists:assistsBy[id]||0,conceded,cleanSheet:conceded===0,rating:Math.max(5.2,Math.min(9.4,6.3+(goalsBy[id]||0)*.75+(assistsBy[id]||0)*.4+(Math.random()-.5)*1.2))});
 for(const id of subs)recordStats(id,{minutes:15,conceded:0,rating:6.1+Math.random()*.8});
 completeDisciplineFixture(career,squadPlayers(clubId).map(p=>p.id),cards,`${career.date}:${clubId}`);
}
function updateHappiness(){
 const minutes=Object.fromEntries(Object.entries(match.participants).map(([id,p])=>[id,Math.max(1,(p.end??90)-p.start)]));
 for(const p of squadPlayers(career.clubId)){
  const state=career.players[p.id],role=ratingRole(p),played=minutes[p.id]||0;
  let delta=0,reason='Content with their squad role.';
  if(played>=45){delta=role==='Starter'?3:7;reason='Pleased with recent playing time.';state.unusedMatches=0}
  else if(played>0){delta=state.ambitious?7:4;reason='A substitute appearance helped.';state.unusedMatches=0}
  else{state.unusedMatches=(state.unusedMatches||0)+1;delta=role==='Starter'?-4:role==='Rotation'?-1:state.ambitious?-3:0;
   reason=role==='Fringe'&&!state.ambitious?'Accepts a fringe role.':role==='Starter'?'Disappointed to miss a start.':state.ambitious?'Wants more playing time.':'Would like more minutes.'}
  state.happiness=Math.max(5,Math.min(96,(state.happiness??70)+delta));state.reason=reason;
  if(state.happiness<25&&state.unusedMatches>=3&&!state.request){state.request=state.happiness<15?'transfer':'loan';state.reason=state.request==='loan'?'Requests a loan for playing time.':'Requests a transfer after limited playing time.';career.news.push({date:career.date,text:`${p.name} has asked to ${state.request==='loan'?'go out on loan':'be transfer listed'}. Review their happiness in Starting XI.`})}
  if(state.happiness<15&&state.request==='loan'&&state.unusedMatches>=6){state.request='transfer';state.reason='Requests a transfer after a long spell without playing.';career.news.push({date:career.date,text:`${p.name} now asks to be transfer listed.`})}
  if(state.happiness>=45)state.request=null;
 }
}
function attentionList(){const unhappy=squadPlayers(career.clubId).filter(p=>career.players[p.id]?.request||moodLevel(p.id)<=1||career.players[p.id]?.injuryDays>0),offers=career.offers.filter(o=>o.status==='new'||o.status==='counter');return `<div class="glass panel attention"><span class="eyebrow">Today / Pay attention</span>${offers.length?`<button class="attention-item" data-action="open-offers">${offers.length} transfer proposal${offers.length===1?'':'s'} to review →</button>`:''}${unhappy.slice(0,3).map(p=>`<button class="attention-item" data-action="focus-player" data-player="${p.id}">${html(p.name)} · ${html(career.players[p.id].injuryDays?`Injured ${injuryLength(career.players[p.id].injuryDays)} — ${career.players[p.id].injuryType||'Knock'}`:career.players[p.id].reason)} →</button>`).join('')}${!offers.length&&!unhappy.length?'<span class="muted">No urgent squad matters today.</span>':''}</div>`}
function toast(message){notice=message;document.querySelector('.toast')?.remove();const div=document.createElement('div');div.className='toast';div.textContent=message;document.body.appendChild(div);setTimeout(()=>div.remove(),3500)}
function stadiumPhase(){if(match?.home===career?.clubId)return match.phase==='live'?'live':match.phase==='report'?'postmatch':'prematch';if(career?.reports?.some(r=>r.home&&r.date===career.date))return 'postmatch';const next=career?nextFixture():null;return next?.home===career?.clubId&&next?.date===career?.date?'prematch':'idle';}
function scene(current,site,open=false,crowd=false,evening=false,wide=false){const layout=career?.clubId===current.id?career.stadium:null,active=career?.clubId===current.id,phase=active?stadiumPhase():'idle',motion=active?{ambient:true,phase}:null;return `<div class="scene ${open?'open':''} ${wide?'menu-scene':''}">${sceneSvg(current,site,crowd,evening,wide?'menu':active?'career':open,layout,null,motion,active?career.construction||[]:[])}${wide?sceneSvg(current,site,crowd,evening,'menu-mobile',layout):''}</div>`;}
function logo(small=false){return `<img class="logo ${small?'small':''}" src="assets/clubline-logo.svg?v=${APP_VERSION}" alt="Clubline 98">`}
function previousBackupAvailable(){try{return !!localStorage.getItem('clubline-before-restore')}catch{return false}}
function backupControls(){return `<section class="career-backup"><h3>Career backup</h3><p>Download a backup to keep your career or move it to another device. Restore previews the file before replacing your current career. Music and notification preferences stay on this device.</p><div class="modal-actions"><button class="btn slim" data-action="backup-export" ${!career&&!hasSave()?'disabled':''}>Download backup</button><button class="btn slim" data-action="backup-import">Restore from file</button>${previousBackupAvailable()?'<button class="btn slim ghost" data-action="backup-previous">Download previous career</button>':''}</div><input type="file" accept=".json,application/json" data-career-import hidden></section>`}
function downloadCareer(save,suffix=''){const json=JSON.stringify(createBackup(save,APP_VERSION)),blob=new Blob([json],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Clubline-${save.career.clubId}-${save.career.date}${suffix}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCareer(previous=false){try{if(!previous&&career&&!save())return toast('Could not save the latest career. Try again after freeing storage.');const raw=localStorage.getItem(previous?'clubline-before-restore':SAVE_KEY);if(!raw)return toast('No saved career to export.');downloadCareer(JSON.parse(raw),previous?'-previous':'');toast('Career backup downloaded.')}catch{toast('Could not download this career backup.')}}
async function readCareerFile(input){const file=input.files?.[0];input.value='';if(!file)return;try{if(file.size>5*1024*1024)throw Error('This backup is too large.');pendingRestore=parseBackup(await file.text(),originalLeague,Object.keys(FORMATIONS),STYLES);render()}catch(error){pendingRestore=null;toast(error.message||'This is not a compatible Clubline backup.')}}
function restorePreview(){if(!pendingRestore)return '';const c=pendingRestore.career;return `<div class="overlay restore-preview" role="dialog" aria-modal="true" aria-label="Restore career"><div class="modal"><h2>Restore this career?</h2><p><b>${html(c.names?.[c.clubId]||club(c.clubId)?.name)}</b> · Season ${c.season||1}</p><p>${fmtDate(c.date)} · Balance ${fmtMoney(c.balance)}</p><p>This replaces the current career on this device. A copy of your previous career will remain available to download in Options. Music, FX and notification settings are retained.</p>${pendingRestore.match?.phase==='live'?'<p>Your live match will be restored paused.</p>':''}<div class="modal-actions"><button class="btn primary" data-action="backup-confirm">Restore career</button><button class="btn" data-action="backup-cancel">Cancel</button></div></div></div>`}
function restoreCareer(){if(!pendingRestore)return;const incoming=structuredClone(pendingRestore),priorCareer=career,priorSource=source,priorMatch=match;let old,previous;if(incoming.match?.phase==='live'){incoming.match.paused=true;incoming.match.pauseReason='manual'}try{old=localStorage.getItem(SAVE_KEY);previous=localStorage.getItem('clubline-before-restore');if(old)localStorage.setItem('clubline-before-restore',old);localStorage.setItem(SAVE_KEY,JSON.stringify(incoming));if(!load())throw Error('Could not load this career.');pendingRestore=null;navOpen=false;focusMode=false;noticesOpen=false;titleOptionsOpen=false;transferReview=null;instructionPlayer=null;selectedPlayer=null;selectedSlot=null;clearInterval(timer);clearTimeout(autoResumeTimer);rotationScroll.clear();view='career';save();render();toast('Career restored.')}catch{career=priorCareer;source=priorSource;match=priorMatch;try{if(old!==undefined){if(old)localStorage.setItem(SAVE_KEY,old);else localStorage.removeItem(SAVE_KEY);if(previous)localStorage.setItem('clubline-before-restore',previous);else localStorage.removeItem('clubline-before-restore');if(old)load()}}catch{}pendingRestore=null;render();toast('Restore failed. Your previous save has been retained.')}}
function titleView(){const shot=menuScenes[titleSceneIndex],c=shot.club,paint=career?.clubId===c.id?career.colour:c.colour;return `<div class="app-shell title-screen" style="--club:${paint}"><div class="title-world" aria-hidden="true" style="background-image:url(assets/sites/${SITE_CATALOGUE.find(x=>x.id===shot.site).art}-${shot.evening?'evening':'day'}.webp?v=${APP_VERSION})"></div><div class="title-backdrop">${menuFrame(titleSceneIndex)}</div><div class="menu-scene-label" data-menu-scene-label>${html(c.name)} · ${html(c.ground)} · ${html(SITES.find(x=>x[0]===shot.site)?.[1])} · ${shot.evening?'Evening':'Day'}</div><div class="shell-content"><div class="menu-hero"><div class="hero-copy glass">${logo()}<p class="title-tagline">Your club. Your call.</p><div class="hero-actions"><button class="btn primary arrow wide" data-action="new-game">New career</button>${hasSave()?'<button class="btn wide" data-action="continue">Continue</button>':''}</div><small>Clubline 98 · 20 clubs · 38 league fixtures</small>${audioControls(true)}<div class="update-area"><button class="btn ghost slim" data-action="check-update" ${checkingUpdate?'disabled':''}>${checkingUpdate?'Checking…':'↻ Check for updates'}</button><span class="build-label">v${APP_VERSION}</span>${availableVersion?'<button class="btn slim primary" data-action="load-update">Load update</button>':''}${updateMessage?`<p role="status">${html(updateMessage)}</p>`:''}</div></div></div></div>${titleOptionsOpen?`<div class="overlay title-options-overlay" role="dialog" aria-modal="true" aria-label="Options"><div class="modal"><div class="modal-head"><h2>Options</h2><button class="btn slim" data-action="close-title-options">Close ×</button></div>${audioControls()}${notificationOptions()}${backupControls()}${gettingStarted()}${leagueRules()}</div></div>`:''}${restorePreview()}</div>`}
async function checkForUpdates(){
 if(checkingUpdate)return;
 checkingUpdate=true;updateMessage='';availableVersion=null;render();
 try{
  const response=await fetch(`./version.json?check=${Date.now()}`,{cache:'no-store'});
  if(!response.ok)throw new Error('Version unavailable');
  const data=await response.json();
  if(!/^\d+\.\d+\.\d+$/.test(data.version))throw new Error('Invalid version');
  const current=APP_VERSION.split('.').map(Number),remote=data.version.split('.').map(Number);
  const newer=remote.some((n,i)=>n>current[i]&&remote.slice(0,i).every((v,j)=>v===current[j]));
  if(newer){availableVersion=data.version;updateMessage=`Clubline v${data.version} is ready.`}
  else updateMessage=`You're up to date (v${APP_VERSION}).`;
 }catch{updateMessage="Couldn't check for updates. Try again when online."}
 checkingUpdate=false;if(view==='title')render();
}
function setupView(){
 const c=club(setup.clubId),name=setup.names[c.id]||c.name,col=setup.colour||c.colour;
 return `<div class="app-shell" style="--club:${col}">${scene({...c,colour:col},setup.site,true)}<div class="shell-content"><header class="topbar">${logo(true)}<button class="btn ghost" data-action="back-title">← Back</button></header><div class="setup-layout"><div class="glass setup-card" data-rotation-scroll="setup-clubs"><span class="eyebrow">01 / Choose your club</span><h2>Premier Division</h2>${clubSelectionTable()}</div><div class="glass setup-detail" data-rotation-scroll="setup-details"><span class="eyebrow">02 / Make it yours</span><h2>${html(name)}</h2><div class="period-kit-selection">${[0,1,2].map((k)=>`<figure><img src="assets/kits/kit-${c.kitIndex}-${k}.svg" alt="${['Home','Away','Goalkeeper'][k]} kit"><figcaption>${['Home','Away','GK'][k]}</figcaption></figure>`).join('')}</div><div class="stat-pair"><div class="stat-block"><small>Attack</small><strong>${c.attack}</strong></div><div class="stat-block"><small>Defence</small><strong>${c.defence}</strong></div><div class="stat-block"><small>Seats</small><strong>${(c.capacity/1000).toFixed(0)}k</strong></div></div><div class="detail-row"><span>Starting style</span><b>${html(c.style)}</b></div><div class="detail-row"><span>Home ground</span><b>${html(c.ground)}</b></div><div class="detail-row"><span>Ground character</span><b>${html(stadiumProfile(c).name)}</b></div><div class="detail-row"><span>Opening funds</span><b>${fmtMoney(c.budget)}</b></div><div class="detail-row"><span>Club facilities</span>${stars(c.facilities,'Club facilities')}</div><div class="detail-row"><span>Youth programme</span>${stars(c.youth,'Youth programme')}</div><label class="field">Your club name<input id="clubRename" maxlength="32" value="${html(name)}"></label><button class="btn slim" data-action="rename-all">${setup.showNames?'Hide division names':'Rename any club'}</button>${setup.showNames?`<div class="list" style="max-height:150px;overflow:auto;margin-top:9px">${source.clubs.map(x=>`<label class="field" style="margin:3px 0">${html(x.name)}<input data-rename="${x.id}" maxlength="32" value="${html(setup.names[x.id]||x.name)}"></label>`).join('')}</div>`:''}<label class="field">Stadium seat colour · period kits retained</label><div class="swatches">${COLOURS.map(x=>`<button class="swatch ${col===x?'on':''}" style="background:${x}" data-action="colour" data-colour="${x}" aria-label="Choose ${x}"></button>`).join('')}<input type="color" id="customColour" aria-label="Custom primary colour" value="${col}" style="width:40px;height:32px;padding:0;border:0;background:transparent"></div><label class="field">Home location</label><div class="site-options">${availableSites(c).map(([key,label,limit])=>`<button class="btn ${setup.site===key?'selected':''}" data-action="site" data-site="${key}">${label}</button>`).join('')}</div><div class="setup-ground-preview" aria-label="Preview of selected home ground">${sceneSvg({...c,colour:col},setup.site,false,false,true)}<span>${html(c.ground)} · ${c.capacity.toLocaleString('en-GB')} seats</span></div><div class="setup-footer"><button class="btn club arrow" data-action="start-season">Start season</button></div></div></div></div></div>`;
}

function clubFixtures(){return career.schedule.flatMap(r=>r.fixtures.filter(f=>f.home===career.clubId||f.away===career.clubId).map(f=>({...f,date:r.date})))}
function topbar(){const next=nextFixture(),rank=standings().findIndex(t=>t.id===career.clubId)+1;return `<header class="topbar career-topbar"><button class="brand-home" data-action="menu" aria-label="Clubline main menu">${logo(true)}</button><div class="league-rank">Premier Division <b>#${rank} / 12</b></div><div class="top-pill date-pill ${Date.now()<dateFlashUntil?'date-flash':''}"><small>Date / time</small><b><span class="header-full">${fmtDate(career.date)} · ${career.time}</span><span class="header-short">${new Date(career.date+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short'})} · ${career.time}</span></b></div><div class="top-pill"><small>Club balance</small><b class="money"><span class="header-full">${fmtMoney(career.balance)}</span><span class="header-short">${Math.abs(career.balance)>=1000000?'£'+(career.balance/1000000).toFixed(2)+'m':fmtMoney(career.balance)}</span></b></div><button class="top-pill next-match-pill" data-action="opponent"><small>Fixtures ⓘ</small><b>${next?`${next.home===career.clubId?'H':'A'} ${next.kickoff||'15:00'} · ${html(clubName(opposition(next,career.clubId)))}`:'Season complete'}</b></button><button class="header-toggle" data-action="header-details" aria-expanded="${headerOpen}" aria-label="${headerOpen?'Collapse':'Expand'} club information">${headerOpen?'Less':'Info'} ▾</button></header>`}
function opponentPanel(){if(!opponentOpen)return '';const list=clubFixtures(),nextIndex=list.findIndex(f=>f.homeGoals===null),current=nextIndex<0?list.length-1:nextIndex,at=fixtureCursor??current,f=list[at],id=opposition(f,career.clubId),c=club(id),results=allResults().filter(x=>x.home===id||x.away===id).slice(-5).reverse(),past=f.homeGoals!==null;return `<div class="overlay" role="dialog" aria-modal="true" aria-label="Season fixture"><div class="modal opponent-modal"><button class="panel-close" data-action="close-opponent" aria-label="Close fixture details">×</button><span class="eyebrow">Fixture ${at+1} of ${list.length} · ${past?'Played':f.date===career.date?'Today':'Upcoming'} / ${f.home===career.clubId?'Home':'Away'}</span><h2>${html(clubName(id))}</h2><p>${fmtDate(f.date)} · ${f.kickoff||'15:00'} · ${html(c.ground)}</p><div class="fixture-switch"><button class="btn slim" data-action="fixture-step" data-step="-1" ${at===0?'disabled':''}>← Previous</button><strong>${past?`${html(clubName(f.home))} ${f.homeGoals}–${f.awayGoals} ${html(clubName(f.away))}`:'vs '+html(clubName(id))}</strong><button class="btn slim" data-action="fixture-step" data-step="1" ${at===list.length-1?'disabled':''}>Next →</button></div><button class="btn slim" data-action="browse-club" data-club="${id}">Scout club / squad →</button>${past?`<button class="btn primary" data-action="open-report" data-index="${at}">View match report</button>`:`<div class="opponent-stats"><div><small>Attack</small><b>${c.attack}</b></div><div><small>Defence</small><b>${c.defence}</b></div><div><small>Style</small><b>${html(c.style)}</b></div><div><small>Ground</small><b>${c.capacity.toLocaleString('en-GB')} seats</b></div></div><h3>Recent results</h3><div class="list">${results.map(x=>`<div class="row"><span>${html(clubName(x.home))} ${x.homeGoals}–${x.awayGoals} ${html(clubName(x.away))}</span><small>${fmtDate(x.date)}</small></div>`).join('')||'<p class="muted">No matches played yet.</p>'}</div>`}<button class="btn slim" data-action="close-opponent">Close</button></div></div>`}
function reportHistoryPanel(){if(reportIndex===null&&!archivedReport)return '';const f=clubFixtures()[reportIndex],r=archivedReport||career.reports.find(x=>x.date===f?.date);if(!r)return '';return `<div class="overlay history-overlay" role="dialog" aria-modal="true" aria-label="Previous match report"><div class="modal history-modal"><button class="panel-close" data-action="close-history" aria-label="Close match report">×</button><span class="eyebrow">Match report / ${fmtDate(r.date)}</span><h2>${html(clubName(career.clubId))} ${r.us}–${r.them} ${html(clubName(r.opponent))}</h2>${reportHeadline(r)}${reportStatistics(r)}<p>${r.home?'Home · '+html(myClub().ground):'Away'} · Attendance ${r.attendance?r.attendance.toLocaleString('en-GB'):'—'} · Tickets ${fmtMoney(r.tickets)} · Food & drink ${fmtMoney(r.concessions)} · Club shop ${fmtMoney(r.shop)} · Operational costs ${fmtMoney(r.operating||0)} · Net income ${fmtMoney(r.income)}</p><div class="match-columns"><div><h3>Player ratings</h3><div class="report-list list">${r.performances.slice().sort((a,b)=>b.rating-a.rating).map(x=>`<div class="row"><span>${html(player(x.id)?.name)}<small style="display:block">${x.minutes} min · ${x.goals||0} goals · ${x.assists||0} assists · Condition ${x.fitness}%${x.injuryDays?' · Injured':''}</small></span><b>${x.rating}</b></div>`).join('')}</div></div><div><h3>Key moments</h3><div class="commentary paused">${r.events.filter(e=>['goal','yellow','red','injury','chance'].includes(e.type)).map(e=>`<div class="comment ${e.type}">${clockLabel(e.minute)} ${html(e.text)}</div>`).join('')||'A quiet game.'}</div></div></div></div></div>`}
function tickerItems(){const items=career.news.filter(n=>n.date===career.date).map(n=>n.text);const round=career.schedule.find(r=>r.date===career.date&&r.fixtures.every(f=>f.homeGoals!==null));if(round)items.push(...round.fixtures.map(f=>`${clubName(f.home)} ${f.homeGoals}–${f.awayGoals} ${clubName(f.away)}`));if(!items.length){const next=nextFixture();items.push(next?`Next fixture: ${clubName(next.home)} v ${clubName(next.away)} · ${fmtDate(next.date)} · ${next.kickoff||'15:00'}`:'Season complete · Open Home to begin the next season.')}return items}
function resultsTicker(){const items=tickerItems();if(!items.length)return '';return `<div class="results-ticker" aria-label="Today's league news"><span class="ticker-label">CLUBLINE LIVE</span><div class="ticker-window"><span data-ticker-text>${html(items[tickerIndex%items.length])}</span></div></div>`}
function homeHub(){const latest=career.reports.at(-1);return `${friendlyInvitationsPanel()}<div class="hub-columns"><div class="hub-news" data-rotation-scroll="hub-news"><h3>${latest?`${latest.us>latest.them?'Victory':latest.us<latest.them?'Defeat':'A point'} against ${html(clubName(latest.opponent))}`:'A new season begins'}</h3>${latest?`<p>${latest.friendly?'Friendly · ':''}${latest.us}–${latest.them} · ${latest.home?'Home':'Away'}</p><button class="btn slim ghost" data-action="news-report" data-date="${latest.date}">Full match report →</button>`:''}<h3>Your club</h3><div class="list">${career.news.filter(isClubNews).slice(-8).reverse().map(n=>`<div class="row"><span>${html(n.text)}${newsAction(n)}</span><small>${fmtDate(n.date)}</small></div>`).join('')||'<p>Set your lineup and prepare for the opening fixture.</p>'}</div><details><summary>Around the league</summary><div class="list">${career.news.filter(n=>!isClubNews(n)).slice(-8).reverse().map(n=>`<div class="row"><span>${html(n.text)}</span><small>${fmtDate(n.date)}</small></div>`).join('')||'<p>The season is about to begin.</p>'}</div></details></div><div class="hub-summary" data-rotation-scroll="hub-summary">${managementSummary()}${expectationsCard()}<details><summary>Youth and development</summary>${developmentHub(false)}</details><button class="btn slim ghost" data-action="open-guide">Getting started →</button>${!nextFixture()?'<button class="btn primary" data-action="new-season">Begin next season</button>':''}</div></div>`}

function leagueTableMarkup(before){const table=standings();return `<div class="table-wrap"><table class="league-table"><thead><tr><th>#</th><th>Club</th><th>P</th><th>W</th><th>D</th><th>L</th><th>GF</th><th>GA</th><th>Pts</th></tr></thead><tbody>${table.map((t,i)=>{const old=before?.[t.id],movement=old===undefined?'':old>i+1?'<span class="rank-up" aria-label="Moved up">▲</span>':old<i+1?'<span class="rank-down" aria-label="Moved down">▼</span>':'';return `<tr class="${t.id===career.clubId?'mine':''}"><td>${i+1} ${movement}</td><td><button class="club-table-link" data-action="browse-club" data-club="${t.id}">${html(clubName(t.id))}</button></td><td>${t.P}</td><td>${t.W}</td><td>${t.D}</td><td>${t.L}</td><td>${t.GF}</td><td>${t.GA}</td><td><b>${t.Pts}</b></td></tr>`}).join('')}</tbody></table></div>`}
function postMatchPanel(){if(!postMatchTable)return '';const report=career.reports.at(-1);return `<div class="overlay" role="dialog" aria-modal="true" aria-label="Premier Division table after matchday"><div class="modal post-table"><span class="eyebrow">After matchday / Premier Division</span><h2>League table</h2>${leagueTableMarkup(report?.tableBefore)}<div class="modal-actions"><button class="btn primary arrow" data-action="close-table">Go to news hub</button></div></div></div>`}

function bottomNav(){const items=[['hub','Home'],['squad','Squad'],['facilities','Facilities'],['finances','Finances'],['organiser','Organiser']],count=notificationGroups().length;return `<nav class="bottom-nav" aria-label="Club navigation"><button class="nav-toggle" data-action="nav-toggle" aria-expanded="${navOpen}" aria-controls="club-menu">Menu ☰</button><div class="nav-drawer" id="club-menu" ${navOpen?'':'hidden'}>${items.map(([id,label])=>`<button class="${careerPanelOpen&&section===id?'active':''}" aria-expanded="${careerPanelOpen&&section===id}" data-action="section" data-section="${id}">${label}</button>`).join('')}<button data-action="nav-toggle" aria-label="Close navigation">Close ×</button></div><button class="notice-toggle" data-action="notice-toggle" aria-expanded="${noticesOpen}" aria-label="Club notifications">News${count?' · '+count:''}</button><button class="focus-toggle" data-action="focus-toggle" aria-pressed="${focusMode}" ${careerPanelOpen?'':'hidden'}>${focusMode?'Restore bars':'Focus ⛶'}</button><button class="bottom-advance" data-action="advance">${career.date===nextFixture()?.date?'Matchday':'Advance'} <span aria-hidden="true">↗</span></button></nav>`}
function syncWorkspaceControls(){const screen=document.querySelector('.career-screen');if(!screen)return;screen.classList.toggle('nav-open',navOpen);screen.classList.toggle('focus-mode',focusMode&&careerPanelOpen&&!match);screen.classList.toggle('header-open',headerOpen);screen.classList.toggle('notices-open',noticesOpen);const drawer=screen.querySelector('.nav-drawer');if(drawer)drawer.hidden=!navOpen;for(const [action,state]of [['nav-toggle',navOpen],['notice-toggle',noticesOpen],['header-details',headerOpen]])screen.querySelector(`[data-action="${action}"]`)?.setAttribute('aria-expanded',state);const news=screen.querySelector('.notice-toggle');if(news){news.textContent='News'+(notificationGroups().length?' · '+notificationGroups().length:'');news.classList.toggle('has-news',notificationGroups().length>0)}const focus=screen.querySelector('.focus-toggle');if(focus){focus.hidden=!careerPanelOpen;focus.textContent=focusMode?'Restore bars':'Focus ⛶';focus.setAttribute('aria-pressed',focusMode)}frameCareerScene();positionPlayerPanel();}
function organiserAside(){const next=nextFixture();return `<aside class="organiser-aside" data-rotation-scroll="organiser-details"><h3>Next fixture</h3>${next?`<p>${fmtDate(next.date)} · ${next.kickoff||'15:00'}</p><b>${html(clubName(next.home))} v ${html(clubName(next.away))}</b><p>${next.home===career.clubId?'Home':'Away'}</p><button class="btn slim" data-action="opponent">Fixture details →</button><button class="btn slim" data-action="browse-club" data-club="${opposition(next,career.clubId)}">Opponent scouting →</button>`:'<p>Season complete.</p>'}<details><summary>League rules</summary>${leagueRules()}</details></aside>`}

function dashboard(sceneMarkup){const c=myClub(),next=nextFixture(),homeMatch=match&&match.home===career.clubId;return `<div class="app-shell career-screen ${careerPanelOpen?'panel-open':''}" style="--club:${myColour()}">${sceneMarkup??scene({...c,colour:myColour()},career.site,false,homeMatch,!!(match&&match.kickoff>='17:30'))}<div class="shell-content">${topbar()}<div class="dash-grid" ${careerPanelOpen?'':'hidden'}><div><div class="glass panel welcome"><span class="eyebrow">${html(c.ground)} / ${usableCapacity(career,c).toLocaleString('en-GB')} seats</span><h1>${html(clubName(c.id))}</h1><div class="next-line">${next?`Next: ${next.home===c.id?'at home to':'away at'} ${html(clubName(opposition(next,c.id)))} · ${fmtDate(next.date)} · ${next.kickoff||'15:00'}`:'The league season is complete.'}</div><button class="btn slim ghost" data-action="open-guide">Getting started</button></div>${saveWarning?`<div class="save-warning" role="alert">${html(saveWarning)}</div>`:''}${attentionList()}<nav class="section-nav" aria-label="Club sections">${[['hub','Home'],['squad','Squad'],['facilities','Facilities'],['finances','Finances'],['organiser','Organiser']].map(([id,label])=>`<button class="btn ${section===id?'active':''}" data-action="section" data-section="${id}">${label}</button>`).join('')}</nav></div><div class="glass panel section-content">${sectionContent()}</div></div><div class="advance-dock" ${careerPanelOpen?'':'hidden'}><button class="btn primary arrow" data-action="advance">${next&&career.date===next.date?'Matchday':'Advance time'}</button><span>${next?`${next.date===career.date?'Kick-off event ahead':'Next fixture '+fmtDate(next.date)}`:'Season finished'}</span></div></div>${careerPanelOpen&&!match?playerPanel():''}<div class="career-view-label">${html(c.ground)} · ${html(SITES.find(x=>x[0]===career.site)?.[1]||career.site)}</div>${resultsTicker()}${bottomNav()}${opponentPanel()}${clubBrowserPanel()}${transferReviewPanel()}${fundingReviewPanel()}${selectionPreviewPanel()}${reportHistoryPanel()}${postMatchPanel()}${match?matchOverlay(!document.querySelector('.match-ground svg')):''}${notificationStack()}${restorePreview()}</div>`}

function sectionContent(){workspaceTabs='';let content=section==='hub'?homeHub():section==='squad'?squadSection():section==='facilities'?facilitiesSection():section==='finances'?financesSection():organiserSection();if(section==='organiser'&&!['options','calendar'].includes(sub))content=`<div class="organiser-columns"><div class="organiser-main" data-rotation-scroll="organiser-main">${content}</div>${organiserAside()}</div>`;const label={hub:'Home',squad:'Squad',facilities:'Facilities',finances:'Finances',organiser:'Organiser'}[section];return `<div class="workspace-head"><strong>${label}</strong>${workspaceTabs}<button class="workspace-close" data-action="close-workspace" aria-label="Return to stadium">×</button></div><div class="workspace-body" data-rotation-scroll="workspace-${section}-${sub}">${content}</div>`}
function tabBar(items){workspaceTabs=`<label class="sub-picker"><span class="sr-only">${section} screen</span><select data-sub-picker aria-label="Choose ${section} screen">${items.map(([key,label])=>`<option value="${key}" ${sub===key?'selected':''}>${label}</option>`).join('')}</select></label>`;return '';}

let archivedReport=null;
function newsAction(n){if(n.reportDate)return `<button class="btn slim ghost" data-action="news-report" data-date="${n.reportDate}">Match report →</button>`;if(n.kind==='offer'){const o=career.offers.find(o=>o.id===n.playerId&&o.clubId===n.buyerId&&['new','counter'].includes(o.status));return o?`<button class="btn slim ghost" data-action="review-offer" data-id="${o.id}" data-club="${o.clubId}">Review offer →</button>`:'<button class="btn slim ghost" data-action="open-offers">Transfers →</button>'}if(n.action)return `<button class="btn slim ghost" data-action="news-review" data-target="${html(n.action)}">${n.action==='training'?'Training report':n.action==='contracts'?'Review contracts':n.action==='coverage'?'Squad cover':n.action==='finances'?'Review finances':'Season expectations'} →</button>`;if(n.kind==='scouting')return `<button class="btn slim ghost" data-action="browse-club" data-club="${n.clubId}">Scouting report →</button>`;if(n.playerId&&player(n.playerId))return `<button class="btn slim ghost" data-action="news-player" data-player="${n.playerId}">${owner(n.playerId)===career.clubId?'Player details':'View club'} →</button>`;const action=n.kind==='development'?'open-development':n.kind==='youth'?'open-youth':n.kind==='conversation'?'open-conversations':null;return action?`<button class="btn slim ghost" data-action="${action}">View →</button>`:''}

function abilityStars(value,label){const stars=estimatedStars(value);return `<span class="youth-stars" aria-label="Estimated ${label}: ${stars} of 5 stars">${'★'.repeat(Math.floor(stars))}${stars%1?'½':''}${'☆'.repeat(5-Math.ceil(stars))} <small>${stars}/5</small></span>`}
function youthSection(){const space=squadSpace(career,source),held=source.players.filter(p=>owner(p.id)===career.clubId&&playerState(p.id).unregistered&&!playerState(p.id).retired);return `<h3>Youth squad · leading prospects</h3><p>Coaches estimate current ability and potential. Exact overall is revealed after promotion; youth form is a guide, not a guarantee of senior success.</p><div class="squad-capacity">Senior ${space.senior}/24 · Under-20 development ${space.development}/5 · Youth system ${youthLevel(career,source).toFixed(1)}/5</div>${held.map(p=>`<div class="youth-card"><b>${html(p.name)} · Age ${p.age}</b><p>${career.developmentIds.includes(p.id)&&p.age<20?'An under-20 development':'A senior'} place is required before they can play.</p><button class="btn slim" data-action="register-senior" data-id="${p.id}">Register in squad</button><button class="btn slim" data-action="focus-player" data-player="${p.id}">Player details / loan</button></div>`).join('')}<div class="youth-grid">${career.prospects.map(p=>`<article class="youth-card"><h3>${html(p.name)}</h3><small>Age ${p.age} · ${p.primary}${p.secondary?' / '+p.secondary:''} · ${html(p.personality)}</small><div class="youth-rating"><span>Current ability</span>${abilityStars(p.overall,'current ability')}</div><div class="youth-rating"><span>Potential</span>${abilityStars(p.potential,'potential')}</div><p>${html(p.report)}</p><small>Traits: ${p.traits.map(html).join(' · ')}</small><p class="muted">${p.form>=7.3?'Youth form: impressing':p.form>=6.5?'Youth form: steady':'Youth form: inconsistent'}</p>${p.promoted?`<span class="badge">Promoted · ${player(p.id).overall} OVR</span>`:`<button class="btn slim primary" data-action="promote-youth" data-id="${p.id}" ${space.development>=5?'disabled':''}>Promote to first team</button>`}</article>`).join('')||'<p>No prospects awaiting assessment.</p>'}</div><p class="muted">Standout reports arrive every three weeks when someone merits attention. Retained youngsters compete with each new annual intake for the five featured places.</p>`}
function developmentSection(){const report=career.developmentReports.at(-1);return `<h3>Squad development</h3><p>A report is prepared three days before each fixture. Ability changes gradually through age, coaching and match experience; one poor performance will not immediately lower attributes.</p>${report?`<span class="eyebrow">${fmtDate(report.date)} · Before ${fmtDate(report.fixture)}</span><div class="development-list">${report.rows.map(row=>`<div class="development-row"><span><b>${html(row.name)}</b><small>${row.position} · Overall ${row.rating}</small><small>${html(row.reason)}</small>${row.positionChanges?.length?`<small>${row.positionChanges.map(html).join(' · ')}</small>`:''}</span><b class="${row.delta>0?'rank-up':row.delta<0?'rank-down':''}">${row.delta>0?'↑ +'+row.delta:row.delta<0?'↓ '+row.delta:'—'}</b></div>`).join('')}</div><details><summary>Previous development reports</summary>${career.developmentReports.slice(0,-1).reverse().map(r=>`<details><summary>${fmtDate(r.date)}</summary>${r.rows.map(x=>`<p>${html(x.name)} · ${x.position} · ${x.delta>0?'+':''}${x.delta} · Overall ${x.rating}</p>`).join('')}</details>`).join('')||'<p>No earlier reports.</p>'}</details>`:'<p>Your first report will be available three days before the next match.</p>'}`}
function conversationSection(){return `<h3>Player conversations</h3><p>Discuss retirement plans and opportunities to develop in another position. Trials improve positional confidence gradually through minutes in the chosen position.</p><div class="list">${career.conversations.slice().reverse().map(c=>{const p=player(c.id);return `<article class="youth-card"><b>${html(p.name)} · Age ${p.age} · ${p.primary}</b><small>${fmtDate(c.date)}</small><p>“${html(c.text)}”</p>${c.status==='new'?c.type==='retirement'?`<button class="btn slim" data-action="conversation-reply" data-key="${c.key}" data-reply="acknowledge">Acknowledge plans</button>`:`<button class="btn slim primary" data-action="conversation-reply" data-key="${c.key}" data-reply="agree">Agree positional trial</button> <button class="btn slim" data-action="conversation-reply" data-key="${c.key}" data-reply="decline">Keep current role</button>`:`<small>${c.status==='agree'?'Trial agreed':c.status==='decline'?'Current role retained':'Plans acknowledged'}</small>`}</article>`}).join('')||'<p>No conversations waiting.</p>'}</div>`}
function investmentCard(kind){const q=investmentStatus(career,source,kind);return `<section class="investment-card" data-investment="${kind}"><div class="investment-heading"><h3>${q.title}</h3><b>${q.level.toFixed(1)}★ / 5</b></div><p class="compact-note">${q.stage}. ${kind==='youth'?'Stronger youth coaching now; improved intake quality from next season. Exceptional talent remains rare.':'Better training facilities support gradual development of registered players aged 24 and under; ability still depends on potential, condition and form.'}</p>${q.complete?'<p class="investment-complete">Five-star standard reached.</p>':`<button class="btn slim" data-action="review-investment" data-kind="${kind}" ${!q.affordable?'disabled':''}>${q.nextStage!==q.stage?q.nextStage:'Improve '+q.stage.toLowerCase()} · ${q.target.toFixed(1)}★ · ${fmtMoney(q.cost)}</button>${!q.affordable?'<small class="investment-shortfall">Insufficient funds for this step.</small>':''}<details class="investment-path"><summary>${q.remaining} improvement${q.remaining===1?'':'s'} available</summary><p>Upgrades add half a star at a time, up to five. Higher standards cost more; prices reflect the club’s starting resources. Each step is paid once and carries into future seasons. No extra weekly charge.</p></details>`}</section>`}
function youthFinance(){return investmentCard('youth')+investmentCard('training')}
function fundingReviewPanel(){if(!fundingReview)return '';const q=investmentStatus(career,source,fundingReview),weekly=squadPlayers(career.clubId).reduce((n,p)=>n+p.wage,0),cash=career.balance-q.cost;return `<div class="overlay funding-review-overlay" role="dialog" aria-modal="true" aria-label="Club investment"><div class="modal"><button class="panel-close" data-action="close-investment" aria-label="Close investment">×</button><h2>${q.title}</h2><p>${q.stage} · ${q.level.toFixed(1)}★ → ${q.target.toFixed(1)}★</p><div class="detail-row"><span>One-off cost</span><b>${fmtMoney(q.cost)}</b></div><div class="detail-row"><span>Cash after investment</span><b>${fmtMoney(cash)}</b></div><div class="detail-row"><span>After four weekly payrolls</span><b>${fmtMoney(cash-weekly*4)}</b></div><p class="compact-note">${fundingReview==='youth'?'Coaching improves immediately. Existing prospects are not replaced or rerated; new intake quality benefits from next season.':'Facilities improve immediately. Development gains accumulate over future training weeks, with no instant overall boost.'} This investment carries into future seasons and has no extra weekly charge.</p>${cash<weekly*4?'<p class="decision-alert">This leaves less than four weekly payrolls in cash. Consider waiting; you can still proceed if you can afford the upgrade.</p>':''}<p class="compact-note">Payroll illustration excludes future match income, transfers and other spending.</p><div class="modal-actions"><button class="btn primary" data-action="confirm-investment" ${!q.affordable?'disabled':''}>Confirm investment</button><button class="btn" data-action="close-investment">Cancel</button></div></div></div>`}
function developmentHub(showSeason=true){const waiting=career.conversations.filter(c=>c.status==='new').length,space=squadSpace(career,source);return `<div class="development-hub"><h3>Squad development · Season ${career.season}</h3><p>Senior ${space.senior}/24 · Under-20 development ${space.development}/5</p><div class="hero-actions"><button class="btn slim" data-action="open-youth">Youth prospects</button><button class="btn slim" data-action="open-development">Development report</button><button class="btn slim" data-action="open-conversations">Conversations${waiting?' · '+waiting:''}</button></div>${squadPlayers(career.clubId).filter(p=>career.developmentIds.includes(p.id)&&p.age===19).map(p=>`<p class="muted">${html(p.name)} turns 20 next season and will need a senior place.</p>`).join('')}${!nextFixture()&&showSeason?'<p>The season is complete. Review the final table before starting a new season.</p><button class="btn primary" data-action="new-season">Begin next season / youth intake</button>':''}</div>`}

function resetTrainingSeason(){const t=career.training;if(!t)return;const reports=t.reports,mode=t.mode,assistant=t.assistant,assignments=t.assignments;career.training={mode,assistant,assignments,reports};initialiseTraining(career,source);}
function trainingReportMarkup(report){if(!report)return '<p>Your first summary arrives after seven days of advancing time.</p>';const rows=report.rows.slice().sort((a,b)=>Number(b.injuryDays>0)-Number(a.injuryDays>0)||Math.abs(b.delta)-Math.abs(a.delta)||b.positionChanges.length-a.positionChanges.length||a.condition-b.condition),line=r=>`<b>${html(r.name)}</b><small>OVR ${r.overall}${r.delta?' ('+(r.delta>0?'+':'')+r.delta+')':''} · CND ${r.condition}%${r.conditionChange?' ('+(r.conditionChange>0?'+':'')+r.conditionChange+')':''}</small><small>${r.injuryDays?'Injured: positional work paused.':r.condition<80?'Needs rest or Fitness focus.':r.delta>0?'Confirmed improvement.':r.delta<0?'Confirmed regression; age and form remain factors.':'No confirmed overall change.'} ${r.positionChanges.map(x=>html(x.position)+' '+(x.delta>0?'+':'')+x.delta).join(' · ')}${r.position&&!r.injuryDays?' · '+html(r.position)+(r.positionReached?' target reached.':' practice: '+r.progress+'% towards next point.'):''}</small>`;return `<p class="compact-note">${fmtDate(report.date)} · ${Object.entries(report.focusDays).filter(([,n])=>n).map(([mode,n])=>mode+' '+n+'d').join(' · ')}. Condition changes include matches and recovery; ability reflects age, form and coaching as well as training.</p><div class="training-report-list">${rows.slice(0,5).map(r=>`<div>${line(r)}</div>`).join('')}</div><details><summary>Full squad report · ${rows.length}</summary><div class="training-report-list">${rows.map(r=>`<div>${line(r)}</div>`).join('')}</div></details>`}
function trainingSection(){const t=initialiseTraining(career,source),effective=trainingMode(career,source,nextFixture()),pool=squadPlayers(career.clubId).sort((a,b)=>comparePositions(a,b)),descriptions={Balanced:'Current development pace and normal condition recovery.',Fitness:'Healthy players recover one extra condition point per day; young-player development runs at 75% of normal.',Development:'Young-player development runs at 135% of normal; healthy players recover one fewer condition point per day (at least one).'};return `<h3>Training & development · ${facilityLevel(career,source).toFixed(1)}★ facilities</h3><div class="training-columns"><section data-rotation-scroll="training-controls"><label class="preference-row"><input type="checkbox" data-training-assistant ${t.assistant?'checked':''}> Assistant manages team focus</label><label class="field">Team focus<select class="select" data-training-mode ${t.assistant?'disabled':''}>${TRAINING_MODES.map(mode=>`<option value="${mode}" ${t.mode===mode?'selected':''}>${mode}</option>`).join('')}</select></label><p class="compact-note"><b>${t.assistant?'Assistant choice':'Selected focus'}: ${effective}.</b> ${descriptions[effective]}</p><details><summary>How training works</summary><p class="compact-note">Choices apply to future days, with no immediate boost or extra fee. Weekly overall development uses the average of the recent daily focuses. The assistant prefers Fitness near fixtures or when the XI is tired; Development when there is time and young players to improve. Balanced keeps the current pace. Existing coaching facilities support training.</p><p class="compact-note">Positional practice develops gradually towards 90% suitability. It pauses while injured and does not train goalkeepers into outfield roles. Match practice from an agreed player conversation can help too. Focus affects registered senior/development-place players; the youth academy keeps its own programme. Training never raises overall beyond potential.</p></details><details class="training-individual" ${career.ui?.trainingPracticeExpanded?'open':''}><summary>Individual positional practice · ${pool.length} players</summary><div class="table-wrap training-table-wrap"><table class="training-table"><thead><tr><th>Player</th><th>Train position</th></tr></thead><tbody>${pool.map(p=>{const a=t.assignments[p.id],state=playerState(p.id);return `<tr><td><button class="club-table-link" data-action="focus-player" data-player="${p.id}">${html(shortPlayerName(p))}</button><small>${p.primary} · ${p.overall} OVR · ${playerFitness(p.id)}% CND</small><small>${state.injuryDays?'✚ Paused while injured':a?`${a.position}: ${Math.floor(positionRatio(p,a.position)*100)}% suitability · ${(p.positions[a.position]||0)>=Math.ceil(p.overall*.9)?'Target reached':Math.min(99,Math.floor((a.progress||0)*100))+'% progress'}`:'No positional programme'}</small></td><td><select data-training-position="${p.id}" aria-label="Training position for ${html(p.name)}" ${p.primary==='GK'?'disabled':''}><option value="">${p.primary==='GK'?'Goalkeeping':'None'}</option>${p.primary==='GK'?'':TRAINING_POSITIONS.filter(pos=>pos!=='GK'&&pos!==p.primary).map(pos=>`<option value="${pos}" ${a?.position===pos?'selected':''}>${pos} · ${Math.floor(positionRatio(p,pos)*100)}%</option>`).join('')}</select></td></tr>`}).join('')}</tbody></table></div></details></section><section data-rotation-scroll="training-report"><h3>Latest training report</h3>${trainingReportMarkup(t.reports.at(-1))}<details><summary>Earlier reports · ${Math.max(0,t.reports.length-1)}</summary>${t.reports.slice(0,-1).reverse().map(r=>`<details><summary>${fmtDate(r.date)}</summary>${trainingReportMarkup(r)}</details>`).join('')||'<p>No earlier reports.</p>'}</details><button class="btn slim" data-action="open-development">Development report →</button></section></div>`}

function squadSection(){
 const tabs=[['lineup','Starting XI'],['coverage','Squad cover'],['training','Training'],['squad-list','Squad list'],['profiles','Player profiles'],['youth','Youth'],['development','Development'],['conversations','Conversations'],['transfers','Transfers'],['statistics','Statistics'],['form','Form charts']];
 let content='';
 if(sub==='lineup') content=lineupEditor(false);
 if(sub==='coverage') content=coverageSection();
 if(sub==='training') content=trainingSection();
 if(sub==='squad-list') content=squadTable();
 if(sub==='profiles') content=playerProfiles();
 if(sub==='youth') content=youthSection();
 if(sub==='development') content=developmentSection();
 if(sub==='conversations') content=conversationSection();
 if(sub==='transfers') content=transfersSection();
 if(sub==='statistics') content=statisticsSection();
 if(sub==='form') content=`<p>Recent league results and the players who have stood out.</p><div class="list">${career.reports.slice(-5).reverse().map(r=>`<div class="row"><span>${fmtDate(r.date)} · ${html(clubName(r.opponent))}</span><b>${r.us}-${r.them}</b></div>`).join('')||'<div class="empty-note">No games played yet.</div>'}</div><div class="divider"></div><div class="list">${career.lineup.filter(Boolean).map(id=>{const p=player(id),form=career.players[id].form;return `<div class="row"><span>${html(p.name)} <small>${p.primary}</small></span><b>${form.length?(form.reduce((a,b)=>a+b,0)/form.length).toFixed(1):'—'}</b></div>`}).join('')}</div>`;
 return `<span class="eyebrow">Football / Squad</span><h2>Shape your eleven</h2>${tabBar(tabs)}${content}`;
}
function playerProfiles(){return `<p>Player attributes, traits and positional confidence. Position colours: green ≥90%, yellow 80–89%, orange 75–79%, red below 75% (60% effectiveness).</p><div class="profile-grid">${squadPlayers(career.clubId).sort((a,b)=>b.overall-a.overall).map(p=>`<button class="profile-row" data-action="focus-player" data-player="${p.id}">${shirt(p,true)}<span><b>${html(p.name)}</b><small>${p.primary} · ${p.overall} OVR · ${p.age} years · ${playerFitness(p.id)}% condition</small><small>${playerTraits(p).join(' · ')}</small></span><span>View ↗</span></button>`).join('')}</div>`}
function statisticsSection(){
 const entries=(statsScope==='club'?squadPlayers(career.clubId):source.players).map(p=>({p,s:career.stats[p.id]||{}}));
 const value=(x,key)=>key==='overall'?x.s.ratedMinutes?(x.s.ratingTotal/x.s.ratedMinutes):0:(x.s[key]||0);
 entries.sort((a,b)=>(value(b,statsSort)-value(a,statsSort))*(statsDescending?1:-1)||value(b,'appearances')-value(a,'appearances')||a.p.name.localeCompare(b.p.name));
 const columns=[['appearances','Apps'],['starts','Starts'],['minutes','Minutes'],['goals','Goals'],['assists','Assists'],['overall','Match OVR'],['conceded','GK conceded'],['cleanSheets','Clean sheets']];
 const head=([key,label])=>`<th><button class="stat-sort ${statsSort===key?'active':''}" data-action="stats-sort" data-sort="${key}" aria-label="Sort by ${label}">${label}${statsSort===key?(statsDescending?' ↓':' ↑'):''}</button></th>`;
 return `<div class="stats-intro"><p>Season performance · AVG is match rating, not base overall.</p><div class="tabs"><button class="btn ${statsScope==='club'?'selected':''}" data-action="stats-scope" data-scope="club">Your club</button><button class="btn ${statsScope==='league'?'selected':''}" data-action="stats-scope" data-scope="league">Premier Division</button></div></div><div class="table-wrap stats-compact-wrap"><table class="stats-compact-table"><colgroup><col style="width:48%"><col><col><col><col></colgroup><thead><tr><th>Player</th>${[['appearances','Apps'],['goals','G'],['assists','A'],['overall','AVG']].map(head).join('')}</tr></thead><tbody>${entries.map(({p,s})=>`<tr class="stats-player-row" data-player="${p.id}"><td><button data-action="${owner(p.id)===career.clubId?'focus-player':'browse-club'}" data-player="${p.id}" data-club="${owner(p.id)}" title="${html(p.name)}">${html(shortPlayerName(p))}</button>${statsScope==='league'?`<small>${html(clubName(owner(p.id)))}</small>`:''}</td><td>${s.appearances||0}</td><td>${s.goals||0}</td><td>${s.assists||0}</td><td>${s.ratedMinutes?(s.ratingTotal/s.ratedMinutes).toFixed(1):'—'}</td></tr>`).join('')}</tbody></table></div><details class="full-statistics" ${fullStatisticsExpanded?'open':''}><summary>All statistics · starts, minutes and goalkeeper records</summary><div class="table-wrap"><table class="league-table player-stats"><thead><tr><th>Player</th><th>Club</th>${columns.map(head).join('')}</tr></thead><tbody>${entries.map(({p,s})=>`<tr class="${owner(p.id)===career.clubId?'mine':''}"><td><b>${html(p.name)}</b><small>${p.primary}</small></td><td>${html(clubName(owner(p.id)))}</td><td>${s.appearances||0}</td><td>${s.starts||0}</td><td>${s.minutes||0}</td><td>${s.goals||0}</td><td>${s.assists||0}</td><td>${s.ratedMinutes?(s.ratingTotal/s.ratedMinutes).toFixed(1):'—'}</td><td>${p.primary==='GK'?(s.conceded||0):'—'}</td><td>${p.primary==='GK'?(s.cleanSheets||0):'—'}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function transferResults(){
 const found=searchLeaguePlayers(source.players,career,transferFilters),rows=found.slice(0,transferLimit);
 return {count:found.length,markup:rows.map(p=>{const own=owner(p.id)===career.clubId,loan=!!career.loans[p.id];return `<div class="transfer-row league-player-row" data-result-player="${p.id}"><label class="hot-list-check"><input type="checkbox" data-hot-player="${p.id}" aria-label="Hot list: ${html(p.name)}" ${career.hotList.includes(p.id)?'checked':''}><span>Hot list</span></label><span><b>${html(p.name)}</b><small>${html(clubName(owner(p.id)))} · Age ${p.age} · ${p.primary} · ${p.overall} OVR</small><small>${fmtMoney(transferValue(p))} · ${career.transferList.includes(p.id)?'Transfer listed':'Not listed'}${loan?' · On loan':''}</small></span><div class="league-player-actions">${own?'<small>Your player</small>':loan?'<small>On loan</small>':`<button class="btn slim" data-action="inquire" data-id="${p.id}">Inquire</button><button class="btn slim primary" data-action="bid" data-id="${p.id}">Bid</button>`}</div></div>`}).join('')||'<div class="empty-note">No players match these filters.</div>'};
}
function transferSearchPanel(){
 const f=transferFilters,results=transferResults();
 const number=(key,label)=>`<label class="field">${label}<input class="input" type="number" min="0" step="${key.startsWith('value')?'1000':'1'}" data-transfer-filter="${key}" value="${html(f[key])}"></label>`;
 const options=(items,value)=>items.map(([id,label])=>`<option value="${id}" ${value===id?'selected':''}>${label}</option>`).join('');
 return `<section class="league-search"><h3>League player search</h3><p class="muted">Search every registered player in the division. Tick players to save them to your hot list.</p><div class="transfer-filters"><label class="field">Name<input class="input" type="search" data-transfer-filter="name" value="${html(f.name)}" placeholder="Player name"></label><label class="field">Transfer status<select class="select" data-transfer-filter="listed">${options([['all','All players'],['listed','Transfer listed'],['unlisted','Not listed']],f.listed)}</select></label><label class="field">Position<select class="select" data-transfer-filter="position">${options([['all','Any position'],['GK','Goalkeeper'],['defence','Defence'],['midfield','Midfield'],['attack','Attack'],...['LB','CB','RB','DM','CM','AM','LW','RW','ST'].map(pos=>[pos,pos])],f.position)}</select></label>${number('valueMin','Minimum value (£)')}${number('valueMax','Maximum value (£)')}${number('ageMin','Minimum age')}${number('ageMax','Maximum age')}${number('ratingMin','Minimum rating')}${number('ratingMax','Maximum rating')}<label class="field">Sort by<select class="select" data-transfer-filter="sort">${options([['rating','Highest rating'],['value','Highest value'],['age','Youngest'],['name','Name A–Z']],f.sort)}</select></label></div><div class="transfer-search-tools"><label class="hot-only"><input type="checkbox" data-transfer-filter="hotOnly" ${f.hotOnly?'checked':''}>Show hot list only</label><button class="btn slim ghost" data-action="reset-transfer-filters">Clear filters</button><span class="muted" id="transfer-result-count">${results.count} players</span></div><div class="transfer-list" id="league-search-results">${results.markup}</div><button class="btn slim" data-action="more-transfer-results" ${results.count<=transferLimit?'hidden':''}>Show more players</button></section>`;
}
function refreshTransferResults(){
 const target=root.querySelector('#league-search-results');if(!target)return;
 const results=transferResults();target.innerHTML=results.markup;root.querySelector('#transfer-result-count').textContent=`${results.count} players`;
 root.querySelector('[data-action="more-transfer-results"]').hidden=results.count<=transferLimit;
}
function handleTransferFilter(el){if(!el.dataset.transferFilter)return false;transferFilters[el.dataset.transferFilter]=el.type==='checkbox'?el.checked:el.value;transferLimit=50;refreshTransferResults();return true}
function transferProfile(p){const state=playerState(p.id),stats=career.stats[p.id]||{},form=state.form||[];return `${p.primary} · ${p.overall} OVR · ${ratingRole(p)} · ${stats.starts||0} starts / ${stats.appearances||0} apps · Form ${form.length?(form.reduce((a,b)=>a+b,0)/form.length).toFixed(1):'—'} · ${MOODS[moodLevel(p.id)][1]} · ${html(state.reason||'Content with their squad role.')} · Contract ${contractStatus(career,p).rolling?'rolling weekly':'until '+contractEnd(career,p)} · Wage ${fmtMoney(p.wage)}/week`}
function recruitmentPanel(open=false){const rec=recruitmentRecommendations(career,source.players,slotsFor(career.formation),scoutKey(career.clubId),recruitmentPosition),space=squadSpace(career,source);return `<details class="recruitment-panel" ${open?'open':''}><summary>Recommended signings · ${rec.rows.length} options</summary><p class="compact-note">For thin positions and expiring deals. Estimated bids leave four weeks of the enlarged payroll in cash; income and other spending are excluded. Fees can be countered.</p><label class="recruitment-filter">Find cover for <select data-recruitment-position><option value="priority" ${recruitmentPosition==='priority'?'selected':''}>Squad priorities</option>${['GK','LB','CB','RB','DM','CM','AM','LW','RW','ST'].map(pos=>`<option value="${pos}" ${recruitmentPosition===pos?'selected':''}>${pos}</option>`).join('')}</select></label>${space.senior>=24?'<p class="decision-alert">All 24 senior places are occupied. Sell or loan out a player before completing a signing.</p>':''}<div class="recommendation-list">${rec.rows.map(({p,fee,assessment:a})=>`<article class="recommendation-card"><div><b>${html(p.name)}</b><span>Age ${p.age} · ${html(clubName(owner(p.id)))} · ${a.role}</span><span>${a.low}–${a.high} estimated effective ability · ${SCOUT_LEVELS[career.scoutingFunding||0].name}</span><p>${a.row?.status==='short'?'Fills a shortage':a.row?.status==='thin'?'Adds a spare option':a.row?.expiring.length?'Covers expiring deals':'Adds competition'} · ${signingVerdict(a)}</p><span>Est. bid ${fmtMoney(fee)} · ${fmtMoney(p.wage)}/wk</span></div><div class="recommendation-actions"><label><input type="checkbox" data-hot-player="${p.id}" ${career.hotList.includes(p.id)?'checked':''}> Hot list</label><button class="btn slim" data-action="bid" data-id="${p.id}" data-role="${a.role}">Review →</button></div></article>`).join('')||`<p>No available players meet this position and cash-reserve limit. ${rec.needs.length?'Try another position or revisit after raising funds.':'Your formation has no current cover or expiry priorities; choose a position to browse.'} Full league search remains below.</p>`}</div></details>`}
function scoutSigningProfile(p){const rating=scoutEstimate(p,career.scoutingFunding||0,scoutKey(career.clubId));return `${p.primary} · ${rating.low}–${rating.high} estimated ability · ${clubAvailability(p.id)} · Contract ${contractStatus(career,p).rolling?'rolling weekly':'until '+contractEnd(career,p)} · Wage ${fmtMoney(p.wage)}/week`;}
function signingVerdict(a){return a.upgrade==='new-option'?'No suitable available competitor':a.upgrade==='likely-upgrade'?'Scouts suggest an upgrade':a.upgrade==='cover'?'Extra cover; below your best option':'Ability overlaps your best option';}
function signingAdvice(p,o){const a=signingAssessment(career,source.players,slotsFor(career.formation),p,scoutKey(career.clubId),o.role),slots=slotsFor(career.formation),before=squadCover(career,squadPlayers(career.clubId),slots),after=squadCover(career,[...squadPlayers(career.clubId),p],slots),space=squadSpace(career,source);return `<section class="signing-advice"><h3>Assistant assessment · ${a.role}</h3><p><b>${signingVerdict(a)}.</b> ${a.low}–${a.high} estimated effective ability${a.best?` against ${a.current} for ${html(a.best.name)}`:''}. ${a.estimate.confidence}; estimates can be wrong.</p><p>${a.row?.status==='short'?'This position currently has too few suitable available players.':a.row?.status==='thin'?'This position currently has no spare suitable player.':a.row?.expiring.length?'This position has expiring contracts to consider.':'This adds competition to a covered position.'} Formation cover ${before.filled}/${before.total} → ${after.filled}/${after.total}.</p><div class="table-wrap signing-comparison"><table><thead><tr><th>Competes with</th><th>Effective</th><th>CND</th></tr></thead><tbody>${a.peers.map(x=>`<tr><td>${html(shortPlayerName(x))}<small>${clubAvailability(x.id)}</small></td><td>${Math.round(x.overall*positionRatio(x,a.role))}</td><td>${playerFitness(x.id)}%</td></tr>`).join('')||'<tr><td colspan="3">No suitable competitors in this role.</td></tr>'}</tbody></table></div><p class="compact-note">Effective ability includes positional suitability; condition is physical readiness. ${space.senior>=24?'A senior squad place must be freed first.':`${24-space.senior} senior place${24-space.senior===1?'':'s'} available.`} Current wage carries into a signing; renewals are in Finances → Contracts.</p></section>`}
function selectionProposal(scope){const plan=scope==='plan'&&match?matchPlan(clubStyle(opposition(match,career.clubId)),clubShape(opposition(match,career.clubId))):null,formation=plan?.formation||career.formation,picks=scope==='bench'?{lineup:[...career.lineup],bench:pickBalancedBench(squadPlayers(career.clubId).filter(p=>!career.lineup.includes(p.id)),7)}:bestLineup(career.clubId,formation,true),slots=slotsFor(formation),changes=picks.lineup.flatMap((id,i)=>{const old=career.lineup[i],p=player(id),previous=player(old);if(id===old&&formation===career.formation)return [];const reason=!p?'No eligible player available.':positionRatio(p,slots[i])<.75?'No suitable cover; this uses an unfamiliar position.':!previous?'Fill the vacant place.':!eligible(old)?'Replace an injured or suspended player.':formation!==career.formation?'Suitable option for the proposed formation.':playerFitness(old)<80&&playerFitness(id)>playerFitness(old)?'Fitter available alternative.':positionRatio(previous,slots[i])<.75?'Improve positional suitability.':'Balance effective ability and condition.';return [{id,old,pos:slots[i],reason}]});const all=[...picks.lineup,...picks.bench],valid=picks.lineup.length===11&&picks.bench.length===7&&all.every(id=>id&&eligible(id))&&new Set(all).size===18;return {scope,plan,formation,picks,changes,valid}}
function selectionPreviewPanel(){if(!selectionPreview)return '';const a=selectionProposal(selectionPreview),added=a.picks.bench.filter(id=>id&&!career.bench.includes(id));return `<div class="overlay selection-preview-overlay" role="dialog" aria-modal="true" aria-label="Assistant selection"><div class="modal"><button class="panel-close" data-action="close-selection" aria-label="Close assistant selection">×</button><h2>Assistant selection</h2><p class="compact-note">${a.formation} · ${a.plan?`${a.plan.style} · ${a.plan.order}. ${html(a.plan.reason)}`:'Balances positional ability and condition. Injured and suspended players are excluded.'} Your selection changes only when you apply it.</p>${a.scope!=='bench'?`<div class="selection-suggestions">${a.changes.map(x=>`<div><b class="${x.id?'suit-'+suitabilityColour(player(x.id),x.pos):'suit-red'}">${x.pos} · ${html(player(x.id)?.name||'Vacant')}</b><small>${x.old?`Replaces ${html(player(x.old)?.name||'vacant')} · `:''}${html(x.reason)}${x.id?` ${player(x.id).overall} OVR · ${playerFitness(x.id)}% CND`:''}</small></div>`).join('')||'<p>No XI changes recommended.</p>'}</div>`:''}<h3>Bench cover</h3><p class="compact-note">Goalkeeper, defensive, midfield and attacking cover where available. ${added.length?'New selections: '+added.map(id=>html(player(id)?.name||'Vacant')).join(', ')+'.':'No changes to the substitutes.'}</p><details><summary>Full proposed XI & bench</summary>${compactPlayers(a.picks.lineup,{positions:slotsFor(a.formation)})}<p class="compact-note">Bench: ${a.picks.bench.map(id=>html(player(id)?.name||'Vacant')).join(' · ')}</p></details>${!a.valid?'<p class="decision-alert">There are not enough eligible players to fill all 18 places. Review the squad manually.</p>':''}<div class="modal-actions"><button class="btn primary" data-action="apply-selection" ${!a.valid?'disabled':''}>Apply ${a.scope==='bench'?'bench':'selection'}</button><button class="btn" data-action="close-selection">Keep my selection</button></div></div></div>`}
function preMatchBrief(){if(!match)return '';const opponent=opposition(match,career.clubId),shape=clubShape(opponent),style=clubStyle(opponent),plan=matchPlan(style,shape),pool=squadPlayers(career.clubId),unavailable=pool.filter(p=>!eligible(p.id)),slots=slotsFor(career.formation),unsuited=career.lineup.map((id,i)=>({p:player(id),pos:slots[i]})).filter(x=>x.p&&positionRatio(x.p,x.pos)<.75),tired=career.lineup.map(player).filter(p=>p&&playerFitness(p.id)<80),cover=squadCover(career,pool,slots),opponentMissing=squadPlayers(opponent).filter(p=>!eligible(p.id)),lineup=bestLineup(opponent,shape).lineup.map(player).filter(Boolean),threats=lineup.filter(p=>['ST','LW','RW','AM'].includes(p.primary)).sort((a,b)=>scoutEstimate(b,career.scoutingFunding,scoutKey(opponent)).centre-scoutEstimate(a,career.scoutingFunding,scoutKey(opponent)).centre).slice(0,2);return `<details class="prematch-brief" ${preMatchBriefOpen?'open':''}><summary>Match briefing · ${shape} · ${validLineup()?'XI & bench ready':'Lineup needs changes'}</summary><div class="brief-grid"><section><h3>Opponent · ${html(clubName(opponent))}</h3><p>${shape} · ${html(style)} · ${SCOUT_LEVELS[career.scoutingFunding||0].name} estimates.</p><p><b>Threats:</b> ${threats.map(p=>html(p.name)+' ('+p.primary+', '+scoutRating(p,opponent)+')').join(' · ')||'No clear attacking standout.'}</p><p><b>Unavailable:</b> ${opponentMissing.map(p=>html(p.name)+' · '+clubAvailability(p.id)).join('; ')||'None reported.'}</p><h3>Suggested plan</h3><p>${plan.formation} · ${plan.style} · ${plan.order}</p><p>${html(plan.reason)}</p><small>Advice is not applied automatically. Use players suited to the suggested roles.</small><button class="btn slim" data-action="selection-preview" data-scope="plan">Review suggested plan →</button></section><section><h3>Your readiness · ${career.formation}</h3><button class="btn slim" data-action="selection-preview" data-scope="xi">Review assistant XI →</button><p><b>Unavailable:</b> ${unavailable.map(p=>html(p.name)+' · '+clubAvailability(p.id)).join('; ')||'None.'}</p><p><b>Condition below 80%:</b> ${tired.map(p=>html(p.name)+' '+playerFitness(p.id)+'%').join(', ')||'None in the XI.'}</p><p><b>Unfamiliar positions:</b> ${unsuited.map(x=>html(x.p.name)+' at '+x.pos).join(', ')||'None in the XI.'}</p><p>${cover.filled}/${cover.total} places can be filled by different suitable available players. ${!validLineup()?'Replace unavailable players and check all 18 selections before kick-off.':'Your XI and seven substitutes are eligible.'}</p></section></div>${matchOpponentPanel()}</details>`}

function transfersSection(){
 career.hotList??=[];
 const my=squadPlayers(career.clubId).sort((a,b)=>b.overall-a.overall);
 return `<p>Scout the division, inquire about availability, and negotiate a fee. Clubs can accept, reject or counter an offer.</p>${recruitmentPanel()}<h3>Transfer proposals</h3><div class="list">${career.offers.filter(o=>o.status==='new'||o.status==='counter').map(o=>`<div class="transfer-row transfer-proposal"><span><b>${html(player(o.id).name)}</b><small>${o.incoming?'Your bid to '+html(clubName(o.clubId)):html(clubName(o.clubId))+' bid'} · ${fmtMoney(o.fee)} ${o.status==='counter'?'counteroffer':'offer'}</small><small class="proposal-profile">${o.incoming?scoutSigningProfile(player(o.id)):transferProfile(player(o.id))}</small></span><div class="proposal-actions"><button class="btn slim primary" data-action="accept-offer" data-id="${o.id}" data-club="${o.clubId}">Accept</button><button class="btn slim" data-action="review-offer" data-id="${o.id}" data-club="${o.clubId}">Review</button><button class="btn slim ghost" data-action="reject-offer" data-id="${o.id}" data-club="${o.clubId}">Reject</button></div></div>`).join('')||'<div class="empty-note">No proposals waiting.</div>'}</div><details class="transfer-listing"><summary>Your squad · ${my.length} players · transfer listing</summary><div class="transfer-list">${my.map(p=>`<div class="transfer-row"><span><b>${html(p.name)}</b><small>${p.primary} · ${p.overall} OVR · value ${fmtMoney(transferValue(p))}</small></span><button class="btn slim ${career.transferList.includes(p.id)?'selected':''}" data-action="list-player" data-id="${p.id}">${career.transferList.includes(p.id)?'Listed ✓':'List'}</button></div>`).join('')}</div></details>${transferSearchPanel()}`;
}
function kitAsset(team,keeper=false,away=false){return `assets/kits/kit-shirt-${club(team)?.kitIndex||1}-${keeper?2:away?1:0}.svg`;}
function shirt(p,compact=false){const team=p?owner(p.id):career?.clubId||setup.clubId,away=!!match&&team===match.away;return `<span class="shirt period-shirt ${compact?'shirt-small':''}"><img src="${kitAsset(team,p?.primary==='GK',away)}" alt="" aria-hidden="true"><b>${p?html(p.number):'–'}</b></span>`;}

function playerPanel(){
 if(!instructionPlayer||owner(instructionPlayer)!==career.clubId)return '';
 const p=player(instructionPlayer),state=playerState(p.id),role=ratingRole(p),[face,label]=MOODS[moodLevel(p.id)];
 return `<div class="player-panel" role="dialog" aria-label="${html(p.name)} instructions"><button class="panel-close" data-action="close-player-panel" aria-label="Minimise player details">−</button><span class="eyebrow">Player / ${html(role)}</span><h3>${html(p.name)} · ${p.primary} · ${p.overall} OVR</h3><span class="player-age">Age ${p.age} · CND ${playerFitness(p.id)}% · FORM ${recentForm(p.id)?.toFixed(1)||'—'}</span><p>Wage ${fmtMoney(p.wage)}/week · Contract ${contractStatus(career,p).rolling?'rolling weekly':'until '+contractEnd(career,p)}</p>${state.retirementAfterSeason?`<p class="muted">Plans to retire after season ${state.retirementAfterSeason}.</p>`:''}${state.positionTrial?`<p class="muted">Positional trial: ${state.positionTrial} · ${state.trialMinutes||0} minutes in that role.</p>`:''}<p>${face} ${label}: ${html(state.reason||'Content with their squad role.')} ${state.ambitious&&role==='Fringe'?'Wants more playing time.':''}</p>${suspensionBadge(p.id)}${state.injuryDays?`<p class="medical-note"><span class="med-cross">✚</span> ${html(state.injuryType||'Injury')} · ${state.injuryDays} days remaining (${injuryLength(state.injuryDays)})</p>`:''}<label class="field">Individual instruction<select class="select" data-player-order="${p.id}">${PLAYER_ORDERS.map(x=>`<option value="${x}" ${state.instruction===x?'selected':''}>${x}</option>`).join('')}</select></label><details class="profile-attributes"><summary>Attributes and positions</summary><div><b>Attributes</b><p>Age ${p.age} · Overall ${p.overall} · Potential ${p.potential} · Condition ${playerFitness(p.id)}% · Season yellows ${state.seasonYellows||0} · Injury risk ${p.risk}/10</p><p>Traits: ${playerTraits(p).map(html).join(' · ')}</p></div><div><b>Positions</b><div class="position-list">${Object.keys(p.positions).filter(pos=>positionRatio(p,pos)>=.75||pos===p.primary).sort((a,b)=>positionRatio(p,b)-positionRatio(p,a)).map(pos=>`<span class="suit-${suitabilityColour(p,pos)}">${positionLabel(p,pos)} · ${effectivePosition(p,pos)} effective</span>`).join('')}</div><small>Other positions: 60% of overall ability.</small></div></details><p class="muted">Substitute appearances usually help players asking for minutes. Individual instructions affect the match plan.</p>${!match&&!career.loans[p.id]?`<button class="btn slim" data-action="offer-loan" data-player="${p.id}">Offer outgoing loan</button>`:''}${state.request==='loan'?'<span class="badge warning">Requests a loan</span>':state.request==='transfer'?`<button class="btn slim" data-action="list-player" data-id="${p.id}">Transfer list player</button>`:''}</div>`;
}
function suitabilityColour(p,pos){const r=positionRatio(p,pos);return r>=.9?'green':r>=.8?'yellow':r>=.75?'orange':'red'}
function recentForm(id){const f=(playerState(id).form||[]).slice(-5);return f.length?f.reduce((a,b)=>a+b,0)/f.length:null}
function shortPlayerName(p){const parts=p.name.split(' ');return parts.length>1?parts[0][0]+'. '+parts.slice(1).join(' '):p.name}
function compactPlayers(ids,{mode='browse',offset=0,positions=null,sortable=false,extra=false}={}){
 const rows=ids.map((id,i)=>({id,i}));if(mode!=='browse')rows.sort((a,b)=>positionRank(positions?.[a.i]||player(a.id)?.primary)-positionRank(positions?.[b.i]||player(b.id)?.primary)||a.i-b.i);
 const cols=[['name','Player'],['position','POS'],['overall','OVR'],['condition','CND'],['form','FORM']];
 return `<div class="table-wrap compact-player-wrap"><table class="squad-table compact-player-table"><colgroup><col class="player-name-col"><col><col><col><col>${extra?'<col><col><col><col>':''}</colgroup><thead><tr>${cols.map(([key,label])=>`<th>${sortable?`<button data-action="squad-sort" data-sort="${key}" aria-label="Sort by ${label}">${label}${squadSort===key?(squadDescending?' ↓':' ↑'):''}</button>`:label}</th>`).join('')}${extra?'<th>Age</th><th>Apps</th><th>G</th><th>A</th>':''}</tr></thead><tbody>${rows.map(({id,i})=>{const p=player(id),condition=mode==='live-xi'&&id?matchInsight(id,career.clubId,positions?.[i]||p?.primary).condition:playerFitness(id),index=i+offset,pos=positions?.[i]||p?.primary||'—',state=p?playerState(id):{},stats=career.stats[id]||{};let attrs='';if(mode==='xi')attrs=`data-action="slot" data-index="${index}" data-drop-slot="${index}"`;else if(mode==='bench')attrs=`data-action="select-player" data-drop-slot="${index}"`;else if(mode==='reserve')attrs=`data-action="select-player" data-drop-player="${id}"`;else if(mode==='live-xi')attrs=`data-action="match-replace" data-index="${index}" data-live-drop="${index}"`;else if(mode==='live-bench')attrs='data-action="match-bench"';const selected=selectedPlayer===id||selectedSlot===index&&mode==='xi',warning=state.injuryDays>0?'✚':state.suspensionMatches>0?'⛔':'';return `<tr class="squad-table-row ${selected?'selected':''} ${mode!=='browse'?'selection-row':''}" data-player="${id||''}" ${attrs} ${mode!=='browse'?'role="button" tabindex="0"':''} draggable="${!!p&&mode!=='browse'&&mode!=='live-xi'}" aria-label="${p?html(p.name)+', '+pos+', overall '+p.overall+', condition '+condition+' percent':pos+' empty'}"><td>${p?`<div class="table-player-name">${mode!=='browse'?shirt(p,true):''}<button class="table-player-info slot-tool" data-action="focus-player" data-player="${id}" title="${html(p.name)} — full player information">${html(shortPlayerName(p))}</button>${warning?`<span class="table-availability" title="${html(clubAvailability(id))}">${warning}</span>`:''}</div>`:'Empty'}</td><td class="suit-${p?suitabilityColour(p,pos):'red'}">${pos}</td><td>${p?p.overall:'—'}</td><td class="${p&&condition<70?'suit-red':p&&condition<85?'suit-orange':'suit-green'}">${p?condition+'%':'—'}</td><td>${p?recentForm(id)?.toFixed(1)||'—':'—'}</td>${extra?`<td>${p?.age||'—'}</td><td>${stats.appearances||0}</td><td>${stats.goals||0}</td><td>${stats.assists||0}</td>`:''}</tr>`}).join('')}</tbody></table></div>`;
}
function squadTable(){
 const group=p=>career.lineup.includes(p.id)?'xi':career.bench.includes(p.id)?'bench':'reserves';
 const value=p=>squadSort==='name'?p.name:squadSort==='condition'?playerFitness(p.id):squadSort==='form'?(recentForm(p.id)??-1):squadSort==='position'?positionRank(p.primary):p[squadSort]??0;
 const pool=squadPlayers(career.clubId).filter(p=>squadFilter==='all'||group(p)===squadFilter).sort((a,b)=>{const x=value(a),y=value(b),d=typeof x==='string'?x.localeCompare(y):x-y;return (squadDescending?-d:d)||a.name.localeCompare(b.name)}).map(p=>p.id);
 return `<div class="squad-table-filters">${[['all','All'],['xi','XI'],['bench','Bench'],['reserves','Reserves']].map(([id,label])=>`<button class="btn slim ${squadFilter===id?'selected':''}" data-action="squad-filter" data-filter="${id}">${label}</button>`).join('')}</div><p class="table-key">CND: condition · FORM: last five ratings · Tap name for details.</p>${compactPlayers(pool,{sortable:true})}<details class="extra-squad-stats"><summary>Age and season statistics</summary>${compactPlayers(pool,{extra:true})}</details>`;
}
function lineupViewControls(){const table=career.ui?.lineupView==='table';return `<div class="lineup-view-controls" aria-label="Lineup view"><button class="btn slim ${!table?'selected':''}" data-action="lineup-view" data-view="shirts" aria-pressed="${!table}">Shirts</button><button class="btn slim ${table?'selected':''}" data-action="lineup-view" data-view="table" aria-pressed="${table}">Table</button><span class="table-key">POS · OVR · CND · FORM</span></div>`}
function clubSelectionTable(){return `<div class="club-table-wrap" tabindex="0" aria-label="Choose a club"><table class="club-selection-table"><colgroup><col class="club-name-col"><col><col><col><col><col><col class="desktop-club-col"><col class="desktop-club-col"></colgroup><thead><tr><th>Club</th><th title="Attack">ATT</th><th title="Defence">DEF</th><th>Seats</th><th title="Facilities out of five">FAC</th><th title="Youth out of five">YTH</th><th class="desktop-club-col">Style</th><th class="desktop-club-col">Funds</th></tr></thead><tbody>${source.clubs.map(c=>`<tr class="${c.id===setup.clubId?'active':''}"><td><button data-action="choose-club" data-id="${c.id}" aria-pressed="${c.id===setup.clubId}"><img class="selection-kit" src="${kitAsset(c.id)}" alt="Home kit">${html(setup.names[c.id]||c.name)}<small class="club-mobile-detail">${html(c.style)} · £${(c.budget/1000000).toFixed(2)}m</small></button></td><td>${c.attack}</td><td>${c.defence}</td><td>${Math.round(c.capacity/1000)}k</td><td>${c.facilities}★</td><td>${c.youth}★</td><td class="desktop-club-col">${html(c.style)}</td><td class="desktop-club-col">${fmtMoney(c.budget)}</td></tr>`).join('')}</tbody></table></div>`}
function livePlayerCard(id,index,action){const p=player(id),pos=index===null?p?.primary:slotsFor(career.formation)[index];return `<div class="live-player-card ${selectedPlayer===id?'selected':''}" role="button" tabindex="0" data-action="${action}" data-player="${id||''}" ${index===null?'draggable="true"':`data-index="${index}" data-live-drop="${index}"`}>${shirt(p,true)}<span><b>${p?html(p.name.split(' ').at(-1))+' ('+p.overall+')':'Vacant'}</b><br><span class="suit-${p?suitabilityColour(p,pos):'red'}">${pos}</span> · CND: ${p?(index===null?playerFitness(id):matchInsight(id,career.clubId,pos).condition)+'%':'—'}</span>${instructionButton(id)}${moodButton(id)}${injuryBadge(id)}${suspensionBadge(id)}</div>`}
function saleAdvice(p,o){const a=saleAssessment(career,source.players,slotsFor(career.formation),p,o.fee);return `<section class="assistant-sale-advice"><h3>Assistant recommendation</h3><b class="status-chip ${a.tone==='green'?'good':a.tone==='red'?'poor':'watch'}">${html(a.verdict)}</b><ul>${a.reasons.map(note=>`<li>${html(note)}</li>`).join('')}</ul><p class="compact-note">Offer: ${Math.round(a.offerRatio*100)}% of estimated value. ${a.available.length} available alternatives in ${p.primary}; suitable players may cover more than one role. This is advice; you decide.</p></section>`}
function transferReviewPanel(){
 const o=transferReview;if(!o)return '';const p=player(o.id);if(!p)return '';const weekly=squadPlayers(career.clubId).reduce((n,x)=>n+x.wage,0),afterWeekly=weekly+(o.incoming?p.wage:-p.wage),cash=career.balance+(o.incoming?-o.fee:o.fee);
 const cover=squadPlayers(career.clubId).filter(x=>x.id!==p.id&&suitsRole(x,p.primary)).sort((a,b)=>effectivePosition(b,p.primary)-effectivePosition(a,p.primary));
 const args=`data-id="${p.id}" data-club="${o.clubId}"`;
 return `<div class="overlay transfer-review-overlay" role="dialog" aria-modal="true" aria-label="Transfer review"><div class="modal"><button class="panel-close" data-action="close-transfer-review" aria-label="Close transfer review">×</button><span class="eyebrow">Transfer review / ${o.incoming?'Signing':'Sale'}</span><h2>${html(p.name)}</h2><p>${html(clubName(o.clubId))} · ${fmtMoney(o.fee)} ${o.bid?'proposed bid':'offer'} · Estimated value ${fmtMoney(transferValue(p))}</p><p class="transfer-review-profile">Age ${p.age} · ${o.incoming?scoutSigningProfile(p):transferProfile(p)}</p><h3>Financial impact</h3><div class="detail-row"><span>Cash after transfer</span><b>${fmtMoney(cash)}</b></div><div class="detail-row"><span>Weekly squad payroll</span><b>${fmtMoney(weekly)} → ${fmtMoney(afterWeekly)}</b></div><div class="detail-row"><span>Cash after four payrolls</span><b>${fmtMoney(cash-afterWeekly*4)}</b></div><p class="muted">Illustration excludes future match income, spending and other transfers. Existing player wage carries into the signing.</p>${cash-afterWeekly*4<0?'<p class="decision-alert">This leaves less than four weekly payrolls in cash. Review your finances before committing.</p>':''}${o.incoming?signingAdvice(p,o):saleAdvice(p,o)}<details class="transfer-cover"><summary>Your ${p.primary} cover · ${cover.length} players</summary><p>${cover.length} other eligible-position players${cover.filter(x=>eligible(x.id)).length!==cover.length?' (some unavailable)':''}. ${!o.incoming&&cover.filter(x=>eligible(x.id)).length===0?'Selling removes your only currently available option in this position.':''}</p><div class="list">${cover.map(x=>`<div class="detail-row"><span>${html(x.name)} · ${x.primary} · Age ${x.age}</span><span>${x.overall} OVR · ${Math.round(positionRatio(x,p.primary)*100)}% suitability · ${clubAvailability(x.id)} · Form ${recentForm(x.id)?.toFixed(1)||'—'}</span></div>`).join('')||'<p>No similar-position cover in your squad.</p>'}</div></details>${!o.incoming?`<label class="field">Counter-offer (£)<input class="input" type="number" min="${o.fee}" step="1000" data-counter-fee value="${Math.round(o.fee*1.2/1000)*1000}"></label><button class="btn" data-action="counter-offer" ${args}>Make counter-offer</button>`:''}<div class="modal-actions"><button class="btn primary" data-action="${o.bid?'submit-bid':'accept-offer'}" data-confirm="true" ${args} ${o.incoming&&(cash<0||!canRegister(career,source,p))?'disabled':''}>${o.bid?'Confirm bid':o.incoming?'Confirm signing':'Accept sale'}</button><button class="btn" data-action="close-transfer-review">Cancel</button></div></div></div>`;
}
function lineupEditor(inModal=false){
 const pool=squadPlayers(career.clubId).filter(p=>!career.lineup.includes(p.id)&&!career.bench.includes(p.id)).sort((a,b)=>b.overall-a.overall);
 const tile=(id,pos,index,compact=false)=>{const p=player(id);return `<div role="button" tabindex="0" class="slot shirt-slot ${!p?'empty':''} ${selectedSlot===index?'selected':''}" data-action="slot" data-index="${index}" data-drop-slot="${index}" data-player="${id||''}" draggable="${!!p}" aria-label="${pos}: ${p?html(p.name)+', rated '+p.overall+', condition '+playerFitness(id)+' percent':'Empty'}">${shirt(p,compact)}<span class="slot-name">${p?`<span class="slot-surname">${html(p.name.split(' ').at(-1))}</span><b class="slot-overall">(${p.overall})</b>`:'Select'}</span><span class="slot-stats"><span class="suit-${p?suitabilityColour(p,pos):'red'}" title="Positional suitability">${pos}</span> · CND: ${p?playerFitness(id)+'%':'—'}</span>${instructionButton(id)}${moodButton(id)}${injuryBadge(id)}${suspensionBadge(id)}</div>`};
 let idx=0;
 const listCard=(p,place,index=null)=>`<div role="button" tabindex="0" draggable="true" ${index!==null?`data-drop-slot="${index}"`:`data-drop-player="${p.id}"`} class="player-card ${selectedPlayer===p.id?'active':''}" data-action="select-player" data-player="${p.id}">${shirt(p,true)}<span class="player-card-copy"><strong>${html(p.name)}</strong><span class="meta">${p.primary}${p.secondary?' / '+p.secondary:''} · ${p.overall} OVR · Age ${p.age} · ${playerFitness(p.id)}% condition</span><span class="meta">${place} · ${ratingRole(p)}</span></span>${instructionButton(p.id)}${moodButton(p.id)}${injuryBadge(p.id)}${suspensionBadge(p.id)}${index!==null?`<button class="bench-target" data-action="slot" data-index="${index}" data-drop-slot="${index}" aria-label="Swap into bench place ${index-10}">↔</button>`:''}</div>`;
 const pitch=FORMATIONS[career.formation].map(line=>`<div class="pitch-line">${line.map(pos=>tile(career.lineup[idx],pos,idx++)).join('')}</div>`).join('');
 return `<div class="lineup-layout"><div class="lineup-main" data-rotation-scroll="lineup-main">${lineupViewControls()}${career.ui?.lineupView==='table'?`<h3 class="table-section-title">Starting XI</h3>${compactPlayers(career.lineup,{mode:'xi',positions:slotsFor(career.formation)})}`:`<div class="formation-pitch">${formationMarkings()}${pitch}</div>`}${[...career.lineup,...career.bench].some(id=>id&&!eligible(id))?`<div class="decision-alert">An injured or suspended player cannot play. Choose an available player from your bench or reserves, or use Auto pick to replace them.</div>`:''}</div><div class="lineup-support" data-rotation-scroll="lineup-support"><details class="lineup-tactics" ${tacticsExpanded?'open':''}><summary>Tactics · ${career.formation} · ${html(career.style)}</summary><div class="squad-toolbar"><label class="field">Formation<select class="select" data-squad-formation>${Object.keys(FORMATIONS).map(f=>`<option value="${f}" ${f===career.formation?'selected':''}>${f}</option>`).join('')}</select></label><label class="field">Play style<select class="select" data-squad-style>${STYLES.map(x=>`<option value="${x}" ${career.style===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Team orders<select class="select" data-squad-order>${ORDERS.map(x=>`<option value="${x}" ${career.order===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn slim" data-action="selection-preview" data-scope="xi">Assistant selection →</button><button class="btn slim" data-action="auto-lineup">Auto pick XI</button><button class="btn slim" data-action="selection-preview" data-scope="bench">Review bench →</button><button class="btn slim" data-action="auto-subs">Auto Pick Subs</button></div></details><button class="squad-list-heading collapse-toggle" data-action="toggle-squad-list" data-list="bench" aria-expanded="${benchExpanded}">Substitutes · ${career.bench.filter(Boolean).length} <span>${benchExpanded?'−':'+'}</span></button><div class="bench-list ${career.ui?.lineupView==='table'?'':'player-list'} ${benchExpanded?'':'collapsed'}">${career.ui?.lineupView==='table'?compactPlayers(career.bench,{mode:'bench',offset:11}):career.bench.map((id,i)=>id?listCard(player(id),'Bench',11+i):`<button class="empty-bench" data-action="slot" data-index="${11+i}" data-drop-slot="${11+i}">Empty bench place ${i+1}</button>`).join('')}</div><button class="squad-list-heading collapse-toggle" data-action="toggle-squad-list" data-list="reserves" aria-expanded="${reservesExpanded}">Reserves · ${pool.length} <span>${reservesExpanded?'−':'+'}</span></button><div class="reserve-list ${career.ui?.lineupView==='table'?'':'player-list'} ${reservesExpanded?'':'collapsed'}">${career.ui?.lineupView==='table'?compactPlayers(pool.map(p=>p.id),{mode:'reserve'}):pool.map(p=>listCard(p,'Reserve')).join('')||'<p class="muted">No additional squad players.</p>'}</div><details class="lineup-help"><summary>Selection help</summary><p>Tap a shirt or row, then a destination; drag shirts to swap. Tap a name in Table view for full details.</p></details></div></div>${inModal?playerPanel():''}${inModal?`<div class="modal-actions"><button class="btn primary" data-action="confirm-lineup" ${!validLineup()?'disabled':''}>Confirm lineup</button></div>`:''}`;
}
function constructionStatus(){const job=career.construction?.[0];return job?`<div class="construction-notice"><b>Stadium work in progress</b><p>${Object.keys(job.sections).length} sections closed · Expected opening ${fmtDate(job.opens)} · ${usableCapacity(career,myClub()).toLocaleString('en-GB')} seats available.</p></div>`:''}
function constructionPreview(q){return `<div class="construction-notice"><b>Construction estimate · ${q.days} days</b><p>Expected opening ${fmtDate(q.opens)}. ${q.closed.toLocaleString('en-GB')} seats will close; ${q.during.toLocaleString('en-GB')} remain available.</p><p>${q.affected.length} home fixture${q.affected.length===1?'':'s'} before reopening.${q.affected.length>=2?' Consider waiting until nearer the end of the season to reduce disruption.':''}</p>${q.during===0?'<p>The whole stadium will be closed: home fixtures will have no paying attendance during works.</p>':''}</div>`}
function stadiumEditor(){
 const c=myClub(),draft=editing||normaliseLayout(career.stadium,c),chosen=draft.sections[selectedStand]||draft.sections.N4;
 const cost=SECTIONS.reduce((sum,x)=>sum+changeCost(career.stadium.sections[x.id],draft.sections[x.id]),0);
 const current=capacity(career.stadium,c),proposed=capacity(draft,c),quote=constructionQuote(career,c,draft);
 const field=(label,key,options)=>`<label class="field">${label}<select class="select" data-stadium-field="${key}">${Object.entries(options).map(([id,value])=>`<option value="${id}" ${chosen[key]===id?'selected':''}>${value.label||value}</option>`).join('')}</select></label>`;
 const buttons=[['N','North side'],['E','East end'],['S','South side'],['W','West end'],['corners','Corners'],['all','Whole ground']];
 return `<span class="eyebrow">Facilities / Stadium designer</span><h2>Build ${html(c.ground)}</h2><div class="facilities-columns"><div class="facilities-visual" data-rotation-scroll="designer-visual"><div class="designer-preview interactive">${sceneSvg({...c,colour:myColour()},career.site,false,false,'designer',draft,selectedStands,{ambient:true,phase:'idle'},career.construction||[])}<span>${proposed.toLocaleString('en-GB')} capacity ${proposed!==current?`· ${proposed>current?'+':''}${(proposed-current).toLocaleString('en-GB')} seats`:''}</span></div><div class="designer-shortcuts">${buttons.map(([id,label])=>`<button class="btn slim" data-action="select-scope" data-scope="${id}">${label}</button>`).join('')}</div></div><div class="facilities-controls" data-rotation-scroll="designer-controls"><div class="designer-selection"><b>${selectedStands.size} section${selectedStands.size===1?'':'s'} selected</b><small>${[...selectedStands].join(' · ')}</small></div><h3>${selectedStands.size===1?`${selectedStand} · ${STANDS[chosen.stand].label}`:'Apply to selected sections'}</h3><div class="designer-fields">${field('Stand and tiers','stand',STANDS)}${field('Roof','roof',ROOFS)}${field('Rear building','rear',REARS)}${field('Exterior','finish',FINISHES)}</div><div class="designer-quote"><span>Current capacity <b>${current.toLocaleString('en-GB')}</b></span><span>Proposed <b>${proposed.toLocaleString('en-GB')}</b></span><span>Build cost <b>${fmtMoney(cost)}</b></span><span>Club cash <b>${fmtMoney(career.balance)}</b></span></div>${constructionStatus()}${cost?constructionPreview(quote):''}<div class="designer-actions"><button class="btn primary" data-action="commit-stadium" ${career.construction?.length||cost===0||cost>career.balance||proposed>siteLimit(career.site)||proposed<10000?'disabled':''}>Start construction</button><button class="btn" data-action="cancel-stadium">Discard preview</button></div>${proposed>siteLimit(career.site)||proposed<10000?`<p class="badge warning">This location can hold 10,000–${(siteLimit(career.site)/1000).toFixed(0)}k.</p>`:''}${cost>career.balance?'<p class="badge warning">Insufficient club funds.</p>':''}</div></div>`;
}

function facilitiesSection(){const c=myClub();return sub==='designer'?stadiumEditor():`<span class="eyebrow">Club / Facilities</span><h2>${html(c.ground)}</h2><div class="facilities-columns"><div class="facilities-visual" data-rotation-scroll="facilities-visual"><div class="designer-preview compact">${sceneSvg({...c,colour:myColour()},career.site,false,false,true,career.stadium,null,{ambient:true,phase:'idle'},career.construction||[])}</div></div><div class="facilities-controls" data-rotation-scroll="facilities-controls"><div class="detail-row"><span>Location</span><b>${html(SITES.find(x=>x[0]===career.site)?.[1])}</b></div><div class="detail-row"><span>Seat colour</span><b><span style="display:inline-block;width:15px;height:15px;background:${myColour()};vertical-align:middle"></span> ${html(myColour().toUpperCase())}</b></div><div class="detail-row"><span>Capacity</span><b>${usableCapacity(career,c).toLocaleString('en-GB')}</b></div>${constructionStatus()}<div class="detail-row"><span>Training facilities</span><b>${facilityLevel(career,source).toFixed(1)}★</b></div><div class="detail-row"><span>Youth academy</span><b>${youthLevel(career,source).toFixed(1)}★</b></div><button class="btn slim" data-action="news-review" data-target="finances">Review club funding →</button><button class="btn primary" data-action="open-designer">Design stadium</button></div></div>`}
function managementSummary(){const pool=squadPlayers(career.clubId),expiring=pool.filter(p=>contractStatus(career,p).expiring),cover=squadCover(career,pool,slotsFor(career.formation)),short=cover.rows.filter(r=>r.status!=='covered');return `<details class="management-summary"><summary>Squad planning · ${expiring.length} expiring · ${short.length} thin positions</summary><p>${nextFixture()?'Renewals are available all season. Plan major decisions for the off-season.':'Off-season: review expiring deals before beginning the next season.'}</p><button class="btn slim" data-action="news-review" data-target="contracts">Contracts →</button> <button class="btn slim" data-action="news-review" data-target="coverage">Squad cover →</button></details>`}
function prepareManagementReminders(){initialiseContracts(career,source);initialiseTraining(career,source);const pool=squadPlayers(career.clubId);contractReminders(career,pool,!nextFixture());const cover=squadCover(career,pool,slotsFor(career.formation)),key=cover.filled<cover.total?`${career.season}:${career.formation}:${pool.filter(p=>!eligible(p.id)||career.loans[p.id]).map(p=>p.id).sort().join(',')}`:null;if(!key){career.coverWarningKey=null;return}if(career.coverWarningKey===key)return;career.coverWarningKey=key;career.news.push({date:career.date,kind:'coverage',action:'coverage',text:`Squad cover: only ${cover.filled}/${cover.total} formation places can be filled by different available, suitable players. Review injuries, suspensions and alternatives in Squad → Squad cover.`});}
function contractsSection(){const pool=squadPlayers(career.clubId).sort((a,b)=>contractEnd(career,a).localeCompare(contractEnd(career,b))||b.wage-a.wage);return `<h3>Contracts & renewals</h3><p class="compact-note">${nextFixture()?'Plan renewals mainly in the off-season; you can negotiate now.':'Off-season: review terms before starting the next season.'} Wages are weekly; renewals have no signing fee.</p><div class="table-wrap contract-wrap"><table class="contract-table"><thead><tr><th>Player</th><th>£/wk</th><th>Ends / left</th><th>Deal</th></tr></thead><tbody>${pool.map(p=>{const t=contractStatus(career,p);return `<tr><td><button class="club-table-link" data-action="focus-player" data-player="${p.id}">${html(p.name)}</button><small>${p.primary} · ${p.overall} OVR · ${p.age}</small></td><td>${fmtMoney(p.wage)}</td><td class="${t.expiring?'contract-warning':''}">${t.rolling?'Rolling weekly':t.end.slice(8)+'/'+t.end.slice(5,7)+'/'+t.end.slice(2,4)}<small>${t.rolling?'Renewal overdue':t.days===0?'Ends today':t.days<31?t.days+'d':Math.floor(t.days/30)+'mo'}${t.expiring&&!t.rolling?' · Expiring':''}</small></td><td><button class="btn slim" data-action="renew-player" data-id="${p.id}">Renew</button></td></tr>`}).join('')}</tbody></table></div>${renewalPanel()}<details><summary>How contracts work</summary><p>Terms end on 30 June. Players whose terms expire stay on rolling weekly contracts at their existing wage until renewed. New weekly wages apply at the next Monday payroll. Offered terms replace the current deal, ending in the selected season; they are not added to it. Longer deals and unhappy players can ask for more.</p></details>`}
function renewalPanel(){const p=player(renewalPlayer);if(!p||owner(p.id)!==career.clubId)return '';const demand=renewalDemand(career,p,2);return `<article class="renewal-panel" aria-label="Contract renewal"><h3>Renew ${html(p.name)}</h3><p>Current ${fmtMoney(p.wage)}/week · ${contractStatus(career,p).rolling?'rolling weekly':'until '+contractEnd(career,p)}.</p><div class="renewal-fields"><label>Weekly wage (£)<input type="number" min="50" max="1000000" step="50" value="${demand}" data-renew-wage></label><label>Term<select data-renew-years>${[1,2,3,4].map(y=>`<option value="${y}" ${y===2?'selected':''}>${y} year${y===1?'':'s'}</option>`).join('')}</select></label></div><p data-renew-preview></p><div class="hero-actions"><button class="btn primary slim" data-action="submit-renewal">Offer renewal</button><button class="btn slim" data-action="close-renewal">Cancel</button></div></article>`}
function updateRenewalPreview(){const p=player(renewalPlayer),out=root.querySelector('[data-renew-preview]');if(!p||!out)return;const wage=Number(root.querySelector('[data-renew-wage]').value),years=Number(root.querySelector('[data-renew-years]').value),change=wage-p.wage,end=`${Number(career.date.slice(0,4))+(career.date.slice(5)>='06-30'?1:0)+years-1}-06-30`;out.textContent=`Player asks ${fmtMoney(renewalDemand(career,p,years))}/week. Offer ends ${end}. Payroll change ${change>=0?'+':''}${fmtMoney(change)}/week; four weeks ${change>=0?'+':''}${fmtMoney(change*4)}. No money is charged today.`;}
root.addEventListener('input',event=>{if(event.target.matches('[data-renew-wage],[data-renew-years]'))updateRenewalPreview()});
root.addEventListener('change',event=>{if(event.target.matches('[data-renew-years]'))updateRenewalPreview()});
function coverageSection(){const cover=squadCover(career,squadPlayers(career.clubId),slotsFor(career.formation));return `<h3>Squad cover · ${career.formation}</h3><p class="compact-note">Suitable means ≥75% positional suitability (natural goalkeepers only). Injured, suspended and loaned-out players are unavailable. Counts show options per position; a versatile player may appear in several rows.</p><p class="${cover.filled<cover.total?'contract-warning':''}"><b>${cover.filled}/${cover.total} places</b> can be filled by different available, suitable players. ${cover.filled<cover.total?'Consider another formation or cover from the transfer market.':'Your current formation can be covered.'}</p><div class="coverage-grid">${cover.rows.map(r=>`<details class="cover-card"><summary><b>${r.pos}</b> · ${r.available.length} available / ${r.need} needed <span class="cover-${r.status}">${r.status==='short'?'Short':r.status==='thin'?'Thin':'Covered'}</span></summary><p>${r.status==='thin'?'No spare suitable option.':r.status==='short'?'Not enough suitable options for this position.':'At least one spare suitable option.'}</p><p><b>Available:</b> ${r.available.map(p=>`<button class="club-table-link" data-action="focus-player" data-player="${p.id}">${html(p.name)} (${p.overall})</button>`).join(', ')||'None'}</p>${r.unavailable.length?`<p><b>Unavailable:</b> ${r.unavailable.map(p=>html(p.name)+' · '+(career.loans[p.id]?'On loan':clubAvailability(p.id))).join('; ')}</p>`:''}${r.expiring.length?`<p class="contract-warning">Expiring: ${r.expiring.map(p=>html(p.name)).join(', ')}.</p><button class="btn slim" data-action="news-review" data-target="contracts">Review contracts →</button>`:''}</details>`).join('')}</div><button class="btn slim" data-action="news-review" data-target="contracts">Contracts →</button> <button class="btn slim" data-action="open-cover-transfers">Transfer search →</button>`}

function financesSection(){tabBar([['lineup','Overview & funding'],['contracts','Contracts']]);if(sub==='contracts')return contractsSection();const home=career.reports.filter(r=>r.home),income=home.reduce((n,r)=>n+r.income,0),med=career.medical||{prevention:0,recovery:0};return `<span class="eyebrow">Club / Finances</span><h2>Club balance</h2><div class="finance-columns"><div class="finance-summary" data-rotation-scroll="finance-summary"><div class="stat-pair"><div class="stat-block"><small>Available cash</small><strong style="font-size:1.7rem">${fmtMoney(career.balance)}</strong></div><div class="stat-block"><small>Net home income</small><strong style="font-size:1.7rem">${fmtMoney(income)}</strong></div></div><p>Wages are processed every Monday for registered players currently at your club. Home matches provide ticket, food and shop income after operating costs; away games bring no home-gate income. Transfers and facility investments are separate spending decisions.</p><div class="detail-row"><span>Weekly squad wages</span><b>${fmtMoney(squadPlayers(career.clubId).reduce((n,p)=>n+p.wage,0))}</b></div>${financeOutlook()}</div><div class="finance-options" data-rotation-scroll="finance-options">${youthFinance()}${scoutingFinance()}<h3>Medical investment</h3><p>One-off investment per level; levels carry into future seasons. Prevention lowers the chance of new injuries; recovery shortens new injuries and speeds existing recoveries.</p><div class="medical-invest"><div><b>Prevention · Level ${med.prevention}/3</b><small>${med.prevention*20}% fewer training and match injuries</small><button class="btn slim" data-action="medical-invest" data-kind="prevention" ${med.prevention>=3||career.balance<(med.prevention+1)*150000?'disabled':''}>Invest ${fmtMoney((med.prevention+1)*150000)}</button></div><div><b>Recovery · Level ${med.recovery}/3</b><small>${med.recovery*12}% shorter new injuries; extra recovery day every ${med.recovery?4-med.recovery:'—'} days</small><button class="btn slim" data-action="medical-invest" data-kind="recovery" ${med.recovery>=3||career.balance<(med.recovery+1)*120000?'disabled':''}>Invest ${fmtMoney((med.recovery+1)*120000)}</button></div></div><div class="detail-row"><span>Matchday pricing</span><b>Standard for the league</b></div></div></div>`}

function leagueRules(){return `<div class="league-rules"><h3>League rules</h3><ul><li>20 clubs, 38 league fixtures: each opponent once at home and once away. Season one opens on 15 August 1998. Win: 3 points; draw: 1. Ties use goal difference, then goals scored.</li><li>Pre-season friendlies are optional invitations. They affect form, condition and injury risk, but do not count towards league statistics, card totals or suspension service. League bans do not prevent friendly appearances.</li><li>Finances use a balanced late-1990s scale. Weekly commercial income and wages are processed on Mondays. League prize money ranges from £325,000 to £1,750,000. Friendly home tickets cost 55% of league prices; away travel costs £3,500.</li><li>Contracts end on 30 June. Unrenewed players stay on rolling weekly terms at their existing wage until you agree a renewal. Renewals have no signing fee; new wages apply at the next Monday payroll.</li><li>Up to seven substitutes; bench places may be empty. Up to three substitutions per team per match. A sent-off player cannot be replaced.</li><li>Any red card, including a second yellow, means suspension for the next league fixture.</li><li>Every five yellow cards in a season triggers a one-match suspension (5, 10, 15…). A second yellow counts as a caution. Overlapping card penalties in one match mean one fixture missed.</li><li>Suspensions are served when your club plays, even if the player is injured. Unserved bans carry into the next season; seasonal yellow totals reset.</li></ul><h3>Reading your squad</h3><p>Condition is physical fitness. Positional suitability: <span class="fit-natural">green ≥90%</span>, <span class="suit-yellow">yellow 80–89%</span>, <span class="suit-orange">orange 75–79%</span>, <span class="fit-unfamiliar">red below 75%</span>. Red positions use 60% of overall ability. ⛔ means suspended; ✚ means injured.</p></div>`}
function scoutKey(id){const f=nextFixture();return `${f?.date||career.date}:${id}`;}
function scoutRating(p,id){const x=scoutEstimate(p,career.scoutingFunding||0,scoutKey(id),id===career.clubId);return x.low===x.high?String(x.low):`${x.low}–${x.high}`;}
function clubShape(id){return id===career.clubId?career.formation:club(id).formation;}
function clubStyle(id){return id===career.clubId?career.style:club(id).style;}
function clubAvailability(id){const state=playerState(id),notes=[];if(state.injuryDays>0)notes.push(`✚ ${html(state.injuryType||'Injured')} · ${injuryLength(state.injuryDays)}`);if(state.suspensionMatches>0)notes.push(`⛔ Suspended · ${state.suspensionMatches} match`);return notes.join(' · ')||'Available';}
function scoutingFinance(){const level=career.scoutingFunding||0,price=scoutingPrice(level);return `<div class="scouting-finance"><h3>Opponent scouting</h3><p>${SCOUT_LEVELS[level].name} · Level ${level}/3. Higher funding narrows ability estimates and reveals more traits and positional detail. Funding lasts to the end of this season; reports remain estimates.</p><button class="btn slim" data-action="scouting-invest" ${level>=3||career.balance<price?'disabled':''}>${level>=3?'Fully funded':`Improve scouting · ${fmtMoney(price)}`}</button></div>`;}
function prepareScoutingReport(){const f=nextFixture();if(!f||!reportDue(career.date,f.date))return;const id=opposition(f,career.clubId),key=`${f.date}:${id}`;career.scoutingReportDates??=[];if(career.scoutingReportDates.includes(key))return;career.scoutingReportDates.push(key);career.news.push({date:career.date,kind:'scouting',clubId:id,fixtureDate:f.date,text:`Scouting report ready: ${clubName(id)}, ${fmtDate(f.date)}. Review their expected lineup and possible tactical approaches.`});}
function leagueClubs(){return `<p>Tap a club to inspect its expected lineup, squad and scout assessments.</p><div class="list">${standings().map((c,i)=>`<button class="row league-club" data-action="browse-club" data-club="${c.id}"><span><b>${i+1}. ${html(clubName(c.id))}</b><small>${clubShape(c.id)} · ${html(clubStyle(c.id))} · ${squadPlayers(c.id).length} players</small></span><span>View →</span></button>`).join('')}</div>`;}
function scoutPlayerProfile(id,teamId){if(!id||!player(id))return '';const p=player(id),level=career.scoutingFunding||0,known=teamId===career.clubId,traits=playerTraits(p),positions=Object.keys(p.positions).filter(pos=>positionRatio(p,pos)>=.75||pos===p.primary),s=career.stats[id]||{};return `<article class="scout-profile"><button class="btn slim ghost" data-action="scout-player" data-player="${id}">Close player ×</button><h3>${html(p.name)} · Age ${p.age}</h3><p>${p.primary} · ${scoutRating(p,teamId)} ${known?'OVR':'estimated ability'} · ${clubAvailability(id)}</p><p>${known||level>=2?traits.map(html).join(' · '):level===1?html(traits[0]):'Traits: further scouting needed.'}</p><div class="position-list">${(known||level>=2?positions:[p.primary]).map(pos=>`<span class="suit-${suitabilityColour(p,pos)}">${pos} · ${pos===p.primary?'Natural':positionTier(p,pos)==='natural'?'Strong':'Suitable'}</span>`).join('')}</div>${!known&&level<2?'<p class="muted">Additional playable positions need more scouting.</p>':''}<p>Season: ${s.appearances||0} appearances · ${s.goals||0} goals · ${s.assists||0} assists · ${s.ratedMinutes?(s.ratingTotal/s.ratedMinutes).toFixed(1):'—'} average performance · ${playerState(id).seasonYellows||0} yellow cards.</p></article>`;}
function recommendedTactics(style,shape){const plan=matchPlan(style,shape);return `<div class="tactical-plan"><p><b>Formation:</b> ${plan.formation} · <b>Style:</b> ${plan.style} · <b>Team orders:</b> ${plan.order}</p><p><b>Individual orders:</b> ${html(plan.individual)}</p><p>${html(plan.reason)}</p><small>Based on their expected shape and style. Check your players’ suitability before changing tactics. Advice is not applied automatically.</small></div>`}
function scoutTeamReport(id,inline=false){const shape=clubShape(id),style=clubStyle(id),picks=bestLineup(id,shape),slots=slotsFor(shape),pool=squadPlayers(id),level=career.scoutingFunding||0,known=id===career.clubId;
 const line=FORMATIONS[shape];let at=0;
 const formation=line.map(group=>`<div class="scout-line">${group.map(pos=>{const pid=picks.lineup[at++],p=player(pid);return `<span class="scout-position">${pos}<b>${p?html(p.name.split(' ').at(-1)):'Vacant'}</b><small>${p?scoutRating(p,id):'—'}</small></span>`;}).join('')}</div>`).join('');
 const units=scoutUnits(picks.lineup.map(player),slots,level,scoutKey(id)),unitNote=units.length>1&&units[0].rating-units.at(-1).rating>=3?`${units[0].name} looks their strongest unit; ${units.at(-1).name.toLowerCase()} appears less strong by comparison.`:'No clear imbalance between their units is apparent.';
 const threats=picks.lineup.map(player).filter(p=>p&&['ST','LW','RW','AM'].includes(p.primary)).sort((a,b)=>scoutEstimate(b,level,scoutKey(id)).centre-scoutEstimate(a,level,scoutKey(id)).centre).slice(0,2);
 const unavailable=pool.filter(p=>!eligible(p.id)),recent=allResults().filter(f=>f.home===id||f.away===id).slice(-3).reverse(),news=career.news.filter(n=>n.clubId===id||pool.some(p=>n.text.includes(p.name))).slice(-3).reverse();
 const row=(p,i=null)=>`<button class="scout-roster-row" data-action="scout-player" data-player="${p.id}"><span class="shirt shirt-small" style="--shirt:${p.primary==='GK'?'#d3a548':id===career.clubId?myColour():club(id).colour}"><b>${p.number}</b></span><span><b>${html(p.name)}</b><small>${i===null?p.primary:slots[i]} · Age ${p.age} · ${scoutRating(p,id)} ${known?'OVR':'est.'}</small><small class="${eligible(p.id)?'muted':'unavailable-text'}">${clubAvailability(p.id)}</small></span><span>View ↗</span></button>`;
 return `<div class="scout-team-report" data-scout-team="${id}"><span class="eyebrow">${known?'Club squad':SCOUT_LEVELS[level].name+' · '+(level>=2?'Higher':'Limited')+' confidence'} · ${fmtDate(career.date)}</span><h3>${html(clubName(id))} · ${shape}</h3><p>${html(style)} style · Expected lineup, subject to changes. ${known?'':'Rating ranges are scout estimates.'}</p><div class="scout-columns"><div class="scout-left" data-rotation-scroll="scout-left"><p class="scout-assessment"><b>Assessment:</b> ${html(unitNote)}</p><details><summary>Expected XI · ${shape}</summary><div class="scout-formation">${formation}</div><div class="scout-roster">${picks.lineup.map((pid,i)=>pid?row(player(pid),i):'<p>Vacant position</p>').join('')}</div></details></div><div class="scout-right" data-rotation-scroll="scout-right"><h3>Recommended match plan</h3>${recommendedTactics(style,shape)}<details class="scout-analysis"><summary>Further tactical analysis</summary>${scoutAdvice(style,shape).map(t=>`<p>${html(t)}</p>`).join('')}<p class="muted">Suggestions, not guaranteed weaknesses. Reassess during the match.</p></details><p><b>Likely threats:</b> ${threats.map(p=>`${html(p.name)} (${p.primary}, ${scoutRating(p,id)} est.)`).join(' · ')||'No clear attacking standout.'}</p><p><b>Unavailable:</b> ${unavailable.map(p=>`${html(p.name)} — ${clubAvailability(p.id)}`).join('; ')||'No reported injuries or suspensions.'}</p><details><summary>Full squad · ${pool.length} players</summary><div class="scout-roster">${pool.sort((a,b)=>comparePositions(a,b)).map(p=>row(p)).join('')}</div></details><div data-club-detail>${scoutPlayerProfile(scoutedPlayer,id)}</div>${news.length?`<details><summary>Club news</summary>${news.map(n=>`<p>${fmtDate(n.date)} · ${html(n.text)}</p>`).join('')}</details>`:''}${recent.length?`<details><summary>Recent results</summary>${recent.map(f=>`<p>${html(clubName(f.home))} ${f.homeGoals}–${f.awayGoals} ${html(clubName(f.away))}</p>`).join('')}</details>`:''}</div></div></div>`;
}
function clubBrowserPanel(){return browsedClub?`<div class="overlay club-browser-overlay" role="dialog" aria-modal="true" aria-label="Club scouting"><div class="modal club-browser-modal"><button class="panel-close" data-action="close-club" aria-label="Close club scouting">×</button>${scoutTeamReport(browsedClub)}<button class="btn" data-action="close-club">Back</button></div></div>`:'';}
function closeClubBrowser(){browsedClub=null;scoutedPlayer=null;opponentOpen=clubReturnFixture;clubReturnFixture=false;render();}
root.addEventListener('toggle',event=>{if(event.target.matches?.('.training-individual')&&event.target.isConnected){career.ui??={};career.ui.trainingPracticeExpanded=event.target.open;}if(event.target.matches?.('.prematch-brief')&&event.target.isConnected)preMatchBriefOpen=event.target.open;if(event.target.matches?.('.full-statistics')&&event.target.isConnected)fullStatisticsExpanded=event.target.open;if(event.target.matches?.('.lineup-tactics')&&event.target.isConnected)tacticsExpanded=event.target.open;if(event.target.matches?.('.match-opponent')&&event.target.isConnected)opponentScoutExpanded=event.target.open;},true);
function matchOpponentPanel(){const id=opposition(match,career.clubId);return `<details class="match-opponent" ${opponentScoutExpanded?'open':''}><summary>Opponent scouting · ${html(clubName(id))} · ${clubShape(id)}</summary>${scoutTeamReport(id,true)}</details>`;}
function calendarView(){
 calendarMonth??=career.date.slice(0,7);calendarDay??=career.date;
 const events=calendarEvents(career),days=monthDays(calendarMonth),selected=events.get(calendarDay)||[],label=new Date(calendarMonth+'-01T12:00:00Z').toLocaleDateString('en-GB',{month:'long',year:'numeric',timeZone:'UTC'});
 const names={fixture:'Match',report:'Report',wages:'Wages',stadium:'Stadium'};
 const eventMarkup=e=>{if(e.kind==='fixture'){const f=e.fixture,played=f.homeGoals!==null;return `<button class="calendar-event" data-action="calendar-fixture" data-index="${e.index}"><span><b>${f.friendly?'Friendly · ':''}${f.home===career.clubId?'Home':'Away'} · ${html(clubName(opposition(f,career.clubId)))}</b><small>${played?`${f.homeGoals}–${f.awayGoals} · Full report →`:(f.kickoff||'15:00')+' · Preview →'}</small></span></button>`}const target=e.kind==='wages'?'finances':e.kind==='stadium'?'facilities':e.news.kind;const attrs=target==='facilities'?'data-action="section" data-section="facilities"':target==='development'?'data-action="open-development"':target==='youth'?'data-action="open-youth"':target==='scouting'?`data-action="browse-club" data-club="${e.news.clubId}"`:`data-action="news-review" data-target="${target}"`;return `<div class="calendar-event"><span><b>${names[e.kind]}</b><small>${e.planned?'Scheduled weekly payroll · amount depends on your squad.':e.opening?'Estimated reopening of the stand under construction.':html(e.news.text)}</small></span><button class="btn slim" ${attrs}>View →</button></div>`};
 return `<div class="calendar-layout"><section class="calendar-month"><div class="calendar-toolbar"><button class="btn slim" data-action="calendar-month" data-delta="-1" aria-label="Previous month">‹</button><b>${label}</b><button class="btn slim" data-action="calendar-month" data-delta="1" aria-label="Next month">›</button><button class="btn slim" data-action="calendar-today">Today</button></div><div class="calendar-weekdays">${['M','T','W','T','F','S','S'].map((day,i)=>`<span aria-label="${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]}">${day}</span>`).join('')}</div><div class="calendar-grid">${days.map(date=>{const dayEvents=events.get(date)||[],kinds=[...new Set(dayEvents.map(e=>e.kind))];return `<button class="calendar-cell ${date.slice(0,7)!==calendarMonth?'outside':''} ${date===career.date?'today':''} ${date===calendarDay?'chosen':''}" data-action="calendar-day" data-date="${date}" aria-pressed="${date===calendarDay}" aria-label="${fmtDate(date)}${kinds.length?': '+kinds.map(k=>names[k]).join(', '):''}"><span>${Number(date.slice(-2))}</span><span class="calendar-dots">${kinds.map(kind=>`<i class="calendar-dot ${kind}" aria-hidden="true"></i>`).join('')}</span></button>`}).join('')}</div><div class="calendar-legend">${Object.entries(names).map(([kind,name])=>`<span><i class="calendar-dot ${kind}"></i>${name}</span>`).join('')}</div></section><section class="calendar-agenda"><h3>${fmtDate(calendarDay)}</h3>${selected.map(eventMarkup).join('')||'<p class="compact-note">No scheduled club events.</p>'}<details class="calendar-archives"><summary>Previous seasons · match reports</summary>${career.archives.map((a,i)=>`<details><summary>Season ${a.season}</summary>${a.reports.map((r,j)=>`<button class="btn slim" data-action="archived-report" data-season="${i}" data-report="${j}">${fmtDate(r.date)} · ${html(clubName(r.opponent))} · ${r.us}–${r.them}</button>`).join('')}</details>`).join('')||'<p>No previous seasons yet.</p>'}</details></section></div>`;
}
function organiserSection(){
 const table=standings(),next=nextFixture(),fixtureLines=clubFixtures();
 return `<span class="eyebrow">Season / Organiser</span><h2>Premier Division</h2>${tabBar([['table','Table'],['calendar','Calendar'],['clubs','Clubs'],['news','News archive'],['options','Options']])}${sub==='options'?audioControls()+notificationOptions()+backupControls()+gettingStarted()+leagueRules():sub==='clubs'?leagueClubs():sub==='calendar'?calendarView():sub==='news'?`<div class="list">${career.news.slice(-12).reverse().map(n=>`<div class="row"><span>${html(n.text)}${newsAction(n)}</span><small>${fmtDate(n.date)}</small></div>`).join('')||'<div class="empty-note">The season is just beginning. Results and injuries will appear here.</div>'}</div>`:`<div class="table-wrap"><table class="league-table"><thead><tr><th>#</th><th>Club</th><th>P</th><th>W</th><th>D</th><th>L</th><th>GF</th><th>GA</th><th>Pts</th></tr></thead><tbody>${table.map((t,i)=>`<tr class="${t.id===career.clubId?'mine':''}"><td>${i+1}</td><td><button class="club-table-link" data-action="browse-club" data-club="${t.id}">${html(clubName(t.id))}</button></td><td>${t.P}</td><td>${t.W}</td><td>${t.D}</td><td>${t.L}</td><td>${t.GF}</td><td>${t.GA}</td><td><b>${t.Pts}</b></td></tr>`).join('')}</tbody></table></div><p style="margin-top:14px">${next?'Next round '+fmtDate(next.date):'Season complete'}</p>`}`;
}

