let dragFrame=0;
function clearTouchDrag(){const pointer=activeDrag?.pointer;activeDrag=null;cancelAnimationFrame(dragFrame);dragFrame=0;dragGhost?.remove();dragGhost=null;dragTarget=null;document.body.classList.remove('shirt-dragging');document.querySelectorAll('.drag-preview,.touch-drag-ghost').forEach(n=>n.remove());document.querySelectorAll('.drop-highlight').forEach(n=>n.classList.remove('drop-highlight'));if(pointer!==undefined&&root.hasPointerCapture?.(pointer))root.releasePointerCapture(pointer)}
function dragHit(){if(!activeDrag)return;const slot=document.elementFromPoint(activeDrag.cx,activeDrag.cy)?.closest('[data-drop-slot],[data-drop-player],[data-live-drop]');if(slot!==dragTarget){dragTarget?.classList.remove('drop-highlight');dragTarget=slot;slot?.classList.add('drop-highlight')}}
function dragScrollChain(start){const chain=[];for(let el=start;el&&el!==document.body;el=el.parentElement)if(el.scrollHeight>el.clientHeight+2&&/(auto|scroll)/.test(getComputedStyle(el).overflowY))chain.push(el);return chain}
function dragVisibleBounds(panel){const r=panel.getBoundingClientRect();let top=Math.max(0,r.top),bottom=Math.min(innerHeight,r.bottom);for(let el=panel.parentElement;el&&el!==document.body;el=el.parentElement)if(/auto|scroll|hidden|clip/.test(getComputedStyle(el).overflowY)){const b=el.getBoundingClientRect();top=Math.max(top,b.top);bottom=Math.min(bottom,b.bottom)}return {top,bottom}}
function scrollDrag(){if(!activeDrag?.moved)return;const over=document.elementFromPoint(activeDrag.cx,activeDrag.cy),chain=[...new Set([...dragScrollChain(over),...dragScrollChain(activeDrag.panel)])];for(const panel of chain){const {top,bottom}=dragVisibleBounds(panel);if(bottom-top<16)continue;const edge=Math.min(56,(bottom-top)*.22),cy=activeDrag.cy;let delta=cy<top+edge?-Math.min(16,Math.max(2,(top+edge-cy)/3)):cy>bottom-edge?Math.min(16,Math.max(2,(cy-bottom+edge)/3)):0;if(!delta)continue;const old=panel.scrollTop;panel.scrollTop+=delta;if(panel.scrollTop!==old){dragHit();break}}dragFrame=requestAnimationFrame(scrollDrag)}
root.addEventListener('pointerdown',event=>{if(activeDrag)clearTouchDrag();if(event.pointerType==='mouse'||event.target.closest('.slot-tool,.bench-target'))return;const card=event.target.closest('.player-card[data-player],.shirt-slot[data-player],.live-player-card[draggable="true"],.selection-row[draggable="true"]');if(!card?.dataset.player)return;let panel=card.parentElement;while(panel&&!(panel.scrollHeight>panel.clientHeight+8&&/(auto|scroll)/.test(getComputedStyle(panel).overflowY)))panel=panel.parentElement;activeDrag={id:card.dataset.player,x:event.clientX,y:event.clientY,cx:event.clientX,cy:event.clientY,pointer:event.pointerId,panel,moved:false,handle:!!event.target.closest('.shirt')};});
document.addEventListener('pointermove',event=>{if(!activeDrag||event.pointerId!==activeDrag.pointer)return;activeDrag.cx=event.clientX;activeDrag.cy=event.clientY;if(!activeDrag.moved&&Math.hypot(event.clientX-activeDrag.x,event.clientY-activeDrag.y)<9)return;if(!activeDrag.moved&&!activeDrag.handle&&Math.abs(event.clientY-activeDrag.y)>Math.abs(event.clientX-activeDrag.x)*1.5){clearTouchDrag();return}event.preventDefault();if(!activeDrag.moved){activeDrag.moved=true;try{root.setPointerCapture(event.pointerId)}catch{}document.body.classList.add('shirt-dragging');dragGhost=document.createElement('div');dragGhost.className='touch-drag-ghost';dragGhost.innerHTML=shirt(player(activeDrag.id));document.body.appendChild(dragGhost);dragFrame=requestAnimationFrame(scrollDrag)}dragGhost.style.left=event.clientX+'px';dragGhost.style.top=event.clientY+'px';dragHit();},{passive:false});
function dropPlayerAt(slot,id){if(!slot)return;if(slot.dataset.liveDrop!==undefined){if(!match?.bench.includes(id))return;selectedPlayer=id;substitute(Number(slot.dataset.liveDrop))}else if(!match||match.phase!=='live'){if(slot.dataset.dropSlot!==undefined)swapLineup(Number(slot.dataset.dropSlot),id);else swapPlayers(id,slot.dataset.dropPlayer)}}
document.addEventListener('pointerup',event=>{if(!activeDrag||event.pointerId!==activeDrag.pointer)return;dragHit();const slot=dragTarget,id=activeDrag.id,moved=activeDrag.moved;clearTouchDrag();if(moved){suppressDragClick=true;setTimeout(()=>suppressDragClick=false,250);dropPlayerAt(slot,id)}});
document.addEventListener('pointercancel',event=>{if(activeDrag?.pointer===event.pointerId)clearTouchDrag()});document.addEventListener('lostpointercapture',event=>{if(event.target===root&&activeDrag?.pointer===event.pointerId&&!root.hasPointerCapture(event.pointerId))clearTouchDrag()});
window.addEventListener('blur',clearTouchDrag);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTouchDrag()});

function notificationGroups(){
 if(!career)return [];const read=new Set(career.noticeRead||[]),groups=new Map();
 const add=(group,key,label,target,id)=>{if(read.has(key)||!notifyEnabled(group))return;let item=groups.get(group);if(!item)groups.set(group,item={group,label,target,id,keys:[]});item.keys.push(key)};
 for(const f of career.friendlyInvitations||[])if(f.status==='offered'&&f.date>=career.date)add('friendlies',f.id,'Pre-season invitations','friendlies');
 for(const o of career.offers||[])if(['new','counter'].includes(o.status))add('offers',`offer:${o.id}:${o.clubId}:${o.fee}:${o.status}`,'Transfer offer','transfers',o.id);
 for(const c of career.conversations||[])if(c.status==='new')add('requests','conversation:'+c.key,'Player request','conversations',c.id);
 for(const p of squadPlayers(career.clubId)){const state=career.players[p.id];if(state.injuryDays>0){const at=career.news.findLastIndex(n=>n.text.includes(p.name)&&/knock|injur|strain|sprain|ligament/i.test(n.text));add('injuries',`injury:${p.id}:${state.injuryType}:${at}`,'Injury update','profiles',p.id)}if(state.suspensionMatches>0){const at=career.news.findLastIndex(n=>n.text.includes(p.name)&&/Suspended/.test(n.text));add('suspensions',`suspension:${p.id}:${at}`,'Suspension update','lineup',p.id)}if(state.request){const at=career.news.findLastIndex(n=>n.text.includes(p.name)&&/loan|transfer/i.test(n.text));add('roles',`request:${p.id}:${state.request}:${at}`,'Squad request','lineup',p.id)}}
 (career.news||[]).forEach((n,i)=>{const key='news:'+i+':'+n.date;if(n.important&&['board','supporters','season-review'].includes(n.kind))add(n.action==='finances'?'board-finances':n.kind,key,n.kind==='season-review'?'End-of-season review':n.kind==='supporters'?'Supporter concern':'Board update',n.action==='finances'?'board-finances':'expectations');if(['contracts','coverage'].includes(n.kind)&&(n.kind==='contracts'?squadPlayers(career.clubId).some(p=>contractStatus(career,p).expiring):squadCover(career,squadPlayers(career.clubId),slotsFor(career.formation)).filled<11)&&i===career.news.findLastIndex(x=>x.kind===n.kind))add(n.kind,key,n.kind==='contracts'?'Contract review':'Squad cover warning',n.kind);if(n.kind==='wages'&&i===career.news.findLastIndex(x=>x.kind==='wages'))add('wages',key,`Weekly wages: ${fmtMoney(n.amount)} · ${fmtDate(n.date)} · Balance ${fmtMoney(n.balance)}`,'finances');if(n.kind==='scouting'&&n.fixtureDate===nextFixture()?.date)add('scouting',key,'Opponent scouting report','scouting',n.clubId);if(['development','youth','stadium','training'].includes(n.kind)&&(n.kind!=='training'||i===career.news.findLastIndex(x=>x.kind==='training')))add(n.kind,key,n.kind==='stadium'?'Stadium update':n.kind==='youth'?'Youth report':n.kind==='training'?'Training report':'Development report',n.kind==='stadium'?'facilities':n.kind);});
 const priority={offers:0,injuries:1,suspensions:1,'board-finances':1,'season-review':1,requests:2,roles:2,board:2,supporters:2,stadium:3,development:4,youth:5,scouting:6,wages:7};return [...groups.values()].sort((a,b)=>(priority[a.group]??5)-(priority[b.group]??5));
}
function notificationStack(){if(match||postMatchTable)return '';const items=notificationGroups(),visible=notificationsExpanded?items:items.slice(0,2);if(!items.length)return '';return `<aside class="notification-stack" aria-label="Club notifications">${visible.map(n=>`<div class="notification-row"><span>${n.label}${n.keys.length>1?' · '+n.keys.length:''}</span><div class="notification-actions"><button data-action="notification" data-group="${n.group}" aria-label="Review ${n.label}">Review →</button><button data-action="notification-dismiss" data-group="${n.group}" aria-label="Dismiss ${n.label}">Dismiss ×</button></div>${['wages','scouting','contracts','coverage','training'].includes(n.group)?`<label class="notice-suppress"><input type="checkbox" data-notice-suppress="${n.group}"> Don’t notify me again</label>`:''}</div>`).join('')}${items.length>2?`<button class="notification-more" data-action="notifications-more">${notificationsExpanded?'Show fewer':(items.length-2)+' more notifications'}</button>`:''}</aside>`}
function openNotification(group){const n=notificationGroups().find(x=>x.group===group);if(!n)return;if(['expectations','board-finances','contracts','coverage'].includes(n.target)){career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];save();openNewsTarget(n.target==='board-finances'?'finances':n.target);return}if(n.target==='friendlies'){careerPanelOpen=true;section='hub';career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];save();render();return;}if(n.target==='scouting'){career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];browsedClub=n.id;scoutedPlayer=null;clubReturnFixture=false;save();render();return;}career.noticeRead=[...new Set([...(career.noticeRead||[]),...n.keys])];careerPanelOpen=true;section=['facilities','finances'].includes(n.target)?n.target:'squad';sub=['facilities','finances'].includes(n.target)?'lineup':n.target;instructionPlayer=null;if(n.id)selectedPlayer=n.id;if(n.target==='lineup'&&n.id){instructionPlayer=n.id;instructionAnchorType='shirt-slot'}save();render();const row=n.id?document.querySelector(`[data-action="accept-offer"][data-id="${n.id}"]`):null;row?.scrollIntoView({block:'center'});}
let historyMoving=false;
function navigationDepth(){if(navOpen||noticesOpen)return (careerPanelOpen?2:1)+1;if(pendingRestore)return view==='title'?2:4;if(view==='title')return titleOptionsOpen?1:0;if(view==='setup')return 1;if(matchExitOpen)return 3;if(match?.phase==='live'&&(match.inspectPlayer||match.drawerOpen))return match.inspectPlayer&&match.drawerOpen?4:3;if(match||postMatchTable)return 2;let depth=careerPanelOpen?2:1;if(careerPanelOpen&&!['lineup','table'].includes(sub))depth++;if((renewalPlayer&&careerPanelOpen&&section==='finances'&&sub==='contracts')||transferReview||fundingReview||selectionPreview||instructionPlayer||opponentOpen||reportIndex!==null||archivedReport||browsedClub)depth++;if(scoutedPlayer)depth++;if(focusMode&&careerPanelOpen&&!match)depth++;return depth;}
function syncNavigation(){if(historyMoving)return;const depth=navigationDepth(),current=history.state?.clublineDepth??0;if(depth<current){historyMoving=true;history.go(depth-current);return}for(let i=current+1;i<=depth;i++)history.pushState({clublineDepth:i},'');history.replaceState({clublineDepth:depth},'');}
function syncMatchExit(){document.querySelector('.match-exit-overlay')?.remove();if(!matchExitOpen||view!=='career')return;root.insertAdjacentHTML('beforeend',`<div class="overlay match-exit-overlay" role="dialog" aria-modal="true" aria-label="Leave match"><div class="modal"><h2>Match paused</h2><p>Your match will be saved if you return to the main menu.</p><div class="modal-actions"><button class="btn primary" data-action="match-return">Return to match</button><button class="btn" data-action="match-menu">Main menu</button></div></div></div>`);}
function returnToMatch(){matchExitOpen=false;if(match?.phase==='live'){match.paused=matchReturnState?.paused||false;match.pauseReason=matchReturnState?.reason||'manual';}save();render();}
function appBack(){
 if(navOpen||noticesOpen){navOpen=false;noticesOpen=false;syncWorkspaceControls();syncNavigation();return}
 if(pendingRestore){pendingRestore=null;render();return}
 if(renewalPlayer&&careerPanelOpen&&section==='finances'&&sub==='contracts'){renewalPlayer=null;render();return}
 if(selectionPreview){selectionPreview=null;render();return}
 if(fundingReview){fundingReview=null;render();return}
 if(transferReview){transferReview=null;render();return}
 if(titleOptionsOpen){titleOptionsOpen=false;render();return}
 if(scoutedPlayer){scoutedPlayer=null;const panel=document.querySelector('[data-club-detail]');if(panel)panel.innerHTML='';syncNavigation();return}
 if(browsedClub){closeClubBrowser();return}
 if(matchExitOpen){returnToMatch();return}
 if(match?.phase==='live'&&match.inspectPlayer){match.inspectPlayer=null;save();render();return}
 if(match?.phase==='live'&&match.drawerOpen){setMatchDrawer(false);return}
 if(instructionPlayer){instructionPlayer=null;render();return}
 if(reportIndex!==null||archivedReport){reportIndex=null;archivedReport=null;render();return}
 if(opponentOpen){opponentOpen=false;render();return}
 if(view==='career'&&match){if(match.phase==='live'){matchReturnState={paused:match.paused&&!['goal','yellow'].includes(match.pauseReason),reason:match.pauseReason};clearTimeout(autoResumeTimer);match.paused=true;match.pauseReason='manual';matchExitOpen=true;save();render();return}if(match.phase==='report'){postMatchTable=!match.friendly;match=null;save();render();return}if(match.phase==='confirm'){match.phase='choice';render();return}match=null;career.time='09:00';save();render();return}
 if(postMatchTable){postMatchTable=false;section='hub';careerPanelOpen=true;render();return}
 if(focusMode&&careerPanelOpen&&!match){focusMode=false;syncWorkspaceControls();syncNavigation();return}
 if(view==='career'&&careerPanelOpen){if(!['lineup','table'].includes(sub)){sub=section==='organiser'?'table':'lineup';instructionPlayer=null;render();return}careerPanelOpen=false;render();return}
 if(view!=='title'){view='title';render();}
}
history.replaceState({clublineDepth:0},'');
window.addEventListener('popstate',event=>{if(!historyMoving&&view==='title'&&!titleOptionsOpen&&event.state?.clublineDepth!=null){history.back();return}if(historyMoving){historyMoving=false;history.replaceState({clublineDepth:navigationDepth()},'');return}appBack();});

render();

if('serviceWorker' in navigator&&location.protocol==='https:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').then(reg=>reg.update()).catch(()=>{}));

function financeOutlook(){
 const weekly=squadPlayers(career.clubId).reduce((n,p)=>n+p.wage,0),next=new Date(career.date+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+((8-next.getUTCDay())%7||7));
 const commercial=myClub().commercialWeekly||0;
 const wageBills=(career.news||[]).filter(n=>['wages','offseason-finance'].includes(n.kind)),home=career.reports.filter(r=>r.home),revenue=home.reduce((n,r)=>n+(r.tickets||0)+(r.concessions||0)+(r.shop||0),0),costs=home.reduce((n,r)=>n+(r.operating||0),0),forecast=career.balance-4*(weekly-commercial);
 return `<div class="detail-row"><span>Home gross revenue · season</span><b>${fmtMoney(revenue)}</b></div><div class="detail-row"><span>Home operating costs · season</span><b>${fmtMoney(costs)}</b></div><h3>Payroll and outlook</h3><div class="detail-row"><span>Weekly commercial income</span><b>${fmtMoney(commercial)}</b></div><p>Wages are deducted every Monday when time advances. Next payroll: ${fmtDate(next.toISOString().slice(0,10))} · ${fmtMoney(weekly)}.</p><div class="detail-row"><span>Four weekly payrolls</span><b>${fmtMoney(4*weekly)}</b></div><div class="detail-row"><span>Balance after four payrolls</span><b class="${forecast<0?'status-red':''}">${fmtMoney(forecast)}</b></div><p>${forecast<0?'Current cash will not cover four payrolls. Review spending and your squad.':'This forecast subtracts wages only; future match income, transfers and investment are excluded.'}</p><p>Funding and upgrades are paid on confirmation; they are not charged again each Monday. Matchday operating costs are deducted from home revenue in each report.</p>${wageBills.length?`<details><summary>Recent wage payments</summary>${wageBills.slice(-6).reverse().map(n=>`<p>${fmtDate(n.date)} · ${fmtMoney(n.amount)} paid · Balance ${fmtMoney(n.balance)}</p>`).join('')}</details>`:''}`;
}

function simulateMinute(){simulationBatch=true;try{tickMatch(true)}finally{simulationBatch=false}}

function ensureAttendance(){if(!match)return;const seats=match.home===career.clubId?usableCapacity(career,myClub()):club(match.home).capacity;if(!Number.isFinite(match.occupancy))match.occupancy=match.friendly?.25+Math.random()*.15:.51+Math.random()*.35;if(!Number.isFinite(match.attendance))match.attendance=Math.round(seats*match.occupancy)}

function isClubNews(n){if(n.kind==='scouting'||n.reportDate)return true;if(n.playerId)return n.clubId?n.clubId===career.clubId:owner(n.playerId)===career.clubId;return !!n.kind||n.text.includes(clubName(career.clubId))||squadPlayers(career.clubId).some(p=>n.text.includes(p.name))}
function openNewsTarget(target){if(!['expectations','finances','contracts','coverage','training'].includes(target))return;careerPanelOpen=true;renewalPlayer=null;section=['coverage','training'].includes(target)?'squad':['finances','contracts'].includes(target)?'finances':'hub';sub=['contracts','coverage','training'].includes(target)?target:'lineup';instructionPlayer=null;render();if(target==='expectations'){const card=document.querySelector('.season-expectations');if(card){card.open=true;card.scrollIntoView({block:'nearest'})}}}
function expectationsCard(){
 const a=assessSeason(career,source,standings()),latest=career.boardReviews.at(-1);
 const indicator=(label,band,score,reasons)=>`<details class="confidence-detail"><summary><span>${label}</span><b class="status-chip ${band.tone}">${band.label}</b></summary><p>${score}/100 · ${reasons.map(html).join(' ')}</p></details>`;
 const review=r=>`<div class="season-review"><h3>Season ${r.season} review</h3><p>Finished ${r.position} · ${r.points} points · Balance ${fmtMoney(r.balance)}</p>${r.objectives.map(o=>`<div class="objective-row"><span>${html(o.title)}</span><b class="status-chip ${o.tone}">${html(o.status)}</b></div>`).join('')}<p>Board: ${r.boardBand.label} · Supporters: ${r.supporterBand.label}</p></div>`;
 return `<details class="season-expectations"><summary><span>Season ${career.season} expectations</span><small>Top ${career.expectations.targetPosition} · Healthy finances</small></summary><p>Targets are set from your club’s starting strength and stay fixed for this season. Confidence is advisory; this version does not dismiss managers.</p>${a.objectives.map(o=>`<div class="objective-row"><span><b>${html(o.title)}</b><small>${html(o.detail)}</small></span><b class="status-chip ${o.tone}">${html(o.status)}</b></div>`).join('')}<div class="hero-actions"><button class="btn slim ghost" data-action="news-review" data-target="finances">Review finances →</button><button class="btn slim ghost" data-action="section" data-section="squad">Review squad →</button></div>${a.complete&&latest?.season===career.season?review(latest):''}${career.boardReviews.filter(r=>r.season!==career.season).length?`<details><summary>Previous season reviews</summary>${career.boardReviews.filter(r=>r.season!==career.season).slice().reverse().map(review).join('')}</details>`:''}</details><div class="confidence-grid">${indicator('Board',a.boardBand,a.board,a.boardReasons)}${indicator('Supporters',a.supporterBand,a.supporters,a.supporterReasons)}</div>`;
}

function friendlyInvitationsPanel(){const invites=(career.friendlyInvitations||[]).filter(x=>x.status==='offered'&&x.date>=career.date);if(!invites.length)return '';return `<section class="friendly-invitations"><h3>Pre-season invitations</h3>${invites.map(f=>{const estimate=friendlyEstimate(career,myClub(),f);return `<article class="friendly-invitation"><b>${html(clubName(f.opponent))} · ${f.home?'Home':'Away'}</b><p>${fmtDate(f.date)} · 15:00 · Friendly</p><small>${f.home?'Estimated net match income '+fmtMoney(estimate.income):'Travel cost '+fmtMoney(estimate.travel)} · Condition and injury risk apply</small><div class="friendly-actions"><button class="btn slim" data-action="accept-friendly" data-id="${f.id}">Accept</button><button class="btn slim ghost" data-action="decline-friendly" data-id="${f.id}">Decline</button></div></article>`}).join('')}</section>`;}

function settleOffSeason(newStart){const weeks=[];for(let date=addDays(career.date,1);date<=newStart;date=addDays(date,1))if(new Date(date+'T12:00:00Z').getUTCDay()===1)weeks.push(date);const weekly=squadPlayers(career.clubId).reduce((n,p)=>n+p.wage,0),commercial=myClub().commercialWeekly||0,wages=weeks.length*weekly,income=weeks.length*commercial;career.balance+=income-wages;if(weeks.length)career.news.push({date:newStart,kind:'offseason-finance',amount:wages,commercial:income,text:`Off-season accounts: ${weeks.length} payrolls, ${fmtMoney(wages)} wages and ${fmtMoney(income)} commercial income. Net ${income>=wages?'+':'−'}${fmtMoney(Math.abs(income-wages))}.`});const elapsed=Math.round((Date.parse(newStart)-Date.parse(career.date))/86400000);for(const state of Object.values(career.players)){state.injuryDays=Math.max(0,(state.injuryDays||0)-elapsed);if(!state.injuryDays)state.injuryType=null;}}
